// js/core/datafix.js が史実馬（と data/legends.js の名馬）に合わせる。名馬の解説（data/famous_*.js）より、こちらが正
(function(){
const HS = globalThis.HS = globalThis.HS || {}; HS.DATA = HS.DATA || {};
HS.DATA.profiles = (HS.DATA.profiles || []).concat([
 { name:'ガーネツト', years:'1957〜1959年', record:'38戦14勝', mainWins:['1959 天皇賞（秋）','1959 有馬記念'],
   text:'1957年8月にデビューした牝馬で、通算38戦14勝の成績を残した。3歳の春は桜花賞とオークスでともに2番人気に推されたが、6着と5着に敗れた。気性の難しさが響いたとされる。4歳の秋に力をつけ、1959年の天皇賞（秋）でオーテモンと並んでゴールし、写真判定のすえハナ差で勝って初めて重賞を制した。続く有馬記念は雨で重馬場になり、12頭立ての9番人気だった。3コーナーから外へ持ち出し、直線では荒れていない外ラチ沿いを伸びて抜け出した。この年を最後に引退して繁殖牝馬になり、仔のウメノダイヤは阪神3歳ステークスと弥生賞で2着に入った。孫のアサクサスケールはクイーンステークスを勝っている。牝系は長く続き、のちにメジロマイヤーやメイショウサムソンが出た。' },
 { name:'カツラシユウホウ', years:'1957〜1960年', record:'25戦13勝', mainWins:['1957 朝日杯3歳ステークス','1958 皐月賞（2着）','1958 東京優駿（2着）','1958 菊花賞（2着）','1959 中京記念'],
   text:'1957年9月に中山の新馬戦でデビューして勝ち、暮れの朝日杯3歳ステークスを重馬場で制した。この年の最優秀3歳牡馬に選ばれている。1958年のクラシックは三競走すべて2着に終わった。皐月賞はレコード決着の接戦でタイセイホープにクビ差、東京優駿は1番人気で逃げるダイゴホマレをハナ差まで追い詰めた。菊花賞もコマヒカリに半馬身及ばなかった。三冠をすべて2着で終えた馬はほかにいない。有馬記念はファン投票1位に選ばれたが、故障で出られなかった。翌年は59キロを背負って中京記念を勝ち、天皇賞（春）はトサオーにクビ差の2着だった。25戦のうち20戦で1番人気に推され、連対を外したのは東京優駿の直後の5着の1度だけだった。引退後は種牡馬になり、母の父としていくつもの勝ち馬を出した。' },
 { name:'ダイゴホマレ', years:'1957〜1959年', record:'24戦14勝', mainWins:['1957 全日本三才優駿','1958 弥生賞','1958 スプリングステークス','1958 NHK杯','1958 東京優駿'],
   text:'大井でデビューし、全日本三才優駿を含めて地方で8戦8勝の成績を残した。中央へ移ると初戦こそ2着だったが、そこから弥生賞とスプリングステークスを含めて3連勝した。1958年の皐月賞は3着に終わった。東京優駿のトライアルだったNHK杯でカツラシユウホウを破ったものの、本番の1番人気はそのカツラシユウホウに譲った。東京優駿は序盤から先頭に立って逃げ、直線で追い上げるカツラシユウホウをハナ差でしのいで勝った。秋は喉鳴りに苦しみ、セントライト記念で大敗した。その後はオープン戦で1勝したが、大きなレースでは勝てないまま引退した。種牡馬としての成績は振るわず、母の父として京都4歳特別のマサイチモンジを出した。' },
 { name:'オーテモン', years:'1957〜1961年', record:'54戦9勝', mainWins:['1959 天皇賞（秋）（2着）','1960 東京記念','1960 日本経済賞','1960 天皇賞（秋）','1960 有馬記念（2着）'],
   text:'1957年10月に中山でデビューした。1勝馬の身で朝日杯3歳ステークスに出て3着に入ったが、翌年の皐月賞と東京優駿はともに14着に沈んだ。菊花賞は連闘で出走し、コマヒカリの3着だった。1959年の天皇賞（秋）はガーネツトと並んでゴールし、写真判定のすえハナ差の2着に敗れた。1960年は東京記念で重賞を初めて勝ち、日本経済賞も制した。秋の天皇賞（秋）は不良馬場で8番人気だったが、オンワードベルとウイルデイールを退けて前年の雪辱を果たした。道悪は苦手とされていた。暮れの有馬記念は1番人気に推されたものの、9番人気のスターロツチに1馬身4分の3差で敗れた。7歳まで走って54戦9勝で引退した。種牡馬としては地方の重賞を勝った産駒を出すにとどまった。' },
 { name:'オンスロート', years:'1959〜1962年', record:'41戦26勝（地方27戦17勝・中央14戦9勝）', mainWins:['1959 全日本三才優駿','1960 秋の鞍','1962 金杯','1962 天皇賞（春）','1962 日本経済賞','1962 有馬記念'],
   text:'1959年7月に大井でデビューした。全日本三才優駿は向正面から早めに仕掛け、2着以下に15馬身差をつけてレコードで勝った。翌年の大井盃と春の鞍ではダイサンコトブキに敗れたが、秋の鞍（のちの東京大賞典）は先頭に立って逃げ切った。地方で27戦17勝を挙げてから中央へ移った。1961年の天皇賞（秋）は大井時代に負かしていたタカマガハラに直線で交わされて2着だった。有馬記念もホマレボシを捉えきれず3着に終わった。1962年は金杯、天皇賞（春）、日本経済賞を勝ち、有馬記念で海外遠征から戻ったタカマガハラを1馬身4分の3差で下して雪辱した。この年の年度代表馬に選ばれている。翌年は脚部不安で引退し、旭川で種牡馬になったが、目立った産駒は出なかった。' },
 { name:'スターロツチ', years:'1959〜1961年', record:'25戦9勝', mainWins:['1960 優駿牝馬','1960 有馬記念','1961 京王杯オータムハンデキャップ'],
   text:'1959年11月に東京でデビューした牝馬。1960年の桜花賞は5番人気で、中団から追い込んだが3着だった。オークスは9番人気の評価を覆し、直線で中団の大外から伸びてクインオンワードを捉えた。クイーンステークスでは60キロを背負って2着に入っている。暮れの有馬記念は12頭立ての9番人気だった。ヘリオスが失速したあと先頭に立ち、1番人気のオーテモンを押さえて勝った。3歳の牝馬が有馬記念を勝ったのはこれが初めてだった。1961年9月に京王杯オータムハンデキャップを勝ったが、次の毎日王冠で右前脚を脱臼して競走を中止し、そのまま引退した。繁殖では自身の仔に大物はいなかったが、孫の代から活躍馬が続いた。牝系からハードバージ、サクラユタカオー、サクラスターオー、ウイニングチケットが出ている。' },
 { name:'ホマレボシ', years:'1960〜1961年', record:'27戦12勝', mainWins:['1960 カブトヤマ記念','1961 ダイヤモンドステークス','1961 安田記念','1961 日本経済賞','1961 有馬記念'],
   text:'1960年2月にデビューした。父はトサミドリで、母クロカミの初めての仔にあたる。3歳の春はNHK盃で3着、東京優駿はコダマの7着に敗れた。秋のカブトヤマ記念で初めて重賞を勝った。1961年は5月の安田記念を61.5キロのハンデでコースレコードで勝ち、7月の日本経済賞も63キロを背負って制した。天皇賞（秋）はタカマガハラ、オンスロートに次ぐ3着だった。同期のタカマガハラ、オンスロート、シーザーらがそろった暮れの有馬記念では1番人気に推された。直線で同期の4頭が競り合うなかから抜け出し、タカマガハラに4分の3馬身差をつけて勝った。この年の年度代表馬に選ばれ、有馬記念を最後に引退した。種牡馬としては後継に恵まれなかった。' },
 { name:'スギヒメ', years:'1960〜1962年', record:'18戦8勝', mainWins:['1961 きさらぎ賞','1961 桜花賞','1961 神戸杯','1962 大阪盃'],
   text:'父はヒンドスタンの牝馬で、1960年10月に阪神の新馬戦でデビューして2着だった。2戦目で勝ち上がるとオープンまで連勝した。1961年は京都の4歳牝馬特別で10着に崩れたが、第1回のきさらぎ賞で初めて重賞を勝った。この年の桜花賞はスターティングゲートが使われ始めた年で、28頭立ての2番人気だった。スタートから逃げてチトセホープに5馬身差をつけた。オークスは逆にチトセホープから4.7秒離された16着に沈んだ。秋は神戸杯を制した。1962年は金鯱賞を勝ったあと、大阪盃で7頭立ての6番人気から逃げ切った。2着は1960年の桜花賞馬トキノキロクで、新旧の桜花賞馬が上位を占めた。デビューから引退まで同じ主戦騎手が乗った。繁殖では9頭の仔を出し、京都記念のニホンピローホマレ、毎日杯と札幌記念のエリモマーチス、ビクトリアカップのエースコスモが走った。' },
 { name:'アズマテンラン', years:'1960〜1961年', record:'13戦7勝', mainWins:['1961 オールカマー','1961 菊花賞'],
   text:'父ザフェニックス、千葉県産の牡馬。母はマーランで、母の父はイギリス産のアークティックプリンスだった。1961年の皐月賞は6番人気で8着に終わった。東京優駿は32頭立ての3番人気に推されたが、18着に沈んだ。秋はセントライト記念で5着に敗れたあと、中山のオールカマーに4番人気で出て勝った。8頭立ての芝2000メートルを2分02秒7で走り、ビツグヨルカを2着に退けた。続く菊花賞は11頭立ての3番人気で、稍重の京都3000メートルを3分15秒4で走った。直線は東京優駿でハナ差の2着だったメジロオーとの叩き合いになり、アタマ差で先着した。3着のホマレタイコウは4馬身離れていた。1番人気のケンロクオーは4着だった。この年の啓衆社賞で最優秀4歳牡馬に選ばれた。通算13戦7勝の成績を残した。' },
 { name:'ハクシヨウ', years:'1960〜1961年', record:'9戦7勝', mainWins:['1960 朝日盃3歳ステークス','1961 東京優駿'],
   text:'1960年に6戦6勝し、最優秀3歳牡馬に選ばれた。東京3歳ステークスを3馬身差、中山3歳ステークスを4馬身差のレコードで勝ち、朝日盃3歳ステークスも2着に5馬身差をつけるレコードだった。1961年の皐月賞は1番人気に推されたが、重馬場でシンツバメの11着に大敗した。NHK盃も4着に終わった。東京優駿は皐月賞馬シンツバメとNHK盃馬チトセミノルが出ず、ふたたび1番人気になった。直線で先行するオークス馬チトセホープを交わしたところへ、23番人気のメジロオーが大外から並びかけた。長い写真判定のすえハナ差の勝ちが決まり、走破タイムはレコードだった。スターティングゲートが入ってから最初のダービー馬にもなった。このレースを最後に引退して種牡馬になったが、地方の勝ち馬を出すにとどまった。' },
 { name:'シンツバメ', years:'1960〜1961年', record:'10戦4勝', mainWins:['1961 皐月賞'],
   text:'父ヒンドスタン、母シラオキの牡馬で、前年の二冠馬コダマの1歳下の半弟にあたる。1961年4月の中山のオープンは1番人気で3着だった。2週後の皐月賞は17頭立ての5番人気で、重馬場を2分10秒1で走った。2着のイカホとはアタマ差、3着のグランドタイムもアタマ差という3頭の接戦を制した。1番人気のハクシヨウは11着に沈んだ。兄に続いて母シラオキの仔が皐月賞を連覇し、母は名繁殖として知られるようになった。東京優駿には出なかった。秋は10月の阪神で6頭立ての6着に敗れている。通算10戦4勝の成績だった。' },
 { name:'ヒカルポーラ', years:'1961〜1965年', record:'40戦16勝', mainWins:['1962 函館記念','1963 阪神大賞典','1964 天皇賞（春）','1964 宝塚記念','1965 京都記念（秋）'],
   text:'父ヒンドスタンの牡馬で、1961年10月に阪神でデビューした。1962年は7番人気で函館記念を勝ち、菊花賞は10番人気から追い込んで3着に入った。そのあと骨折して長く休み、1963年10月に戻ってきた。阪神大賞典ではモトイチをアタマ差退けて重賞2勝目を挙げた。天皇賞（秋）はリユウフオーレルとの一騎打ちになり、クビ差の2着に敗れた。1964年の天皇賞（春）は3番人気で、直線で先頭のメイズイを差し切り4分の3馬身差で勝った。続く宝塚記念は1番人気に応え、パスポートとの競り合いをハナ差で制した。同じ年に天皇賞（春）と宝塚記念を勝ったのはこれが初めてだった。暮れの有馬記念は1番人気で5着に沈み、ヤマトキヨウダイに1秒離された。1965年はシンザンと3度戦ってすべて敗れ、有馬記念の6着を最後に引退した。種牡馬としては南関東で重賞を5勝したマルイチキングを出した。' },
 { name:'ヤマノオー', years:'1961〜1964年', record:'29戦8勝', mainWins:['1962 皐月賞','1962 東京優駿（2着）','1963 ダイヤモンドステークス','1963 安田記念','1963 日本経済賞','1963 毎日王冠'],
   text:'父ハクリョウの牡馬。母はミスツキトシ、母の父はトシシロで、父にとっては3年目の産駒にあたる。1962年の皐月賞は17頭立ての13番人気だったが、1番人気のカネツセーキに1馬身4分の1差をつけて勝った。走破タイムは2分04秒8で、単勝は124.8倍だった。東京優駿では2番人気に推されたが、フエアーウインに4分の3馬身及ばず2着だった。2着はコレヒサとの同着で、ダービーで2着が同着になったのはこれが初めてだった。1963年はダイヤモンドステークスを勝ち、続いて安田記念、秋の毎日王冠も制した。安田記念のあとは6月に中山2600メートルの日本経済賞も勝ち、この年は重賞を4勝した。この年の天皇賞（秋）は3番人気だったが、リユウフオーレルの12着に大敗した。1964年春の東京で4着に敗れ、次の出走を取り消して競走生活を終えた。通算29戦8勝の成績だった。' },
 { name:'グレートヨルカ', years:'1962〜1968年', record:'34戦11勝', mainWins:['1962 朝日盃3歳ステークス','1963 東京記念','1963 セントライト記念','1963 菊花賞','1966 京王杯スプリングハンデキャップ'],
   text:'3戦目で初勝利を挙げ、そこから朝日盃3歳ステークスと東京記念を含めて6連勝した。1962年の最優秀3歳牡馬に選ばれている。1963年は同じ厩舎のメイズイにスプリングステークス、皐月賞、東京優駿と3度続けて敗れ、いずれも2着だった。秋はセントライト記念を勝って菊花賞に向かった。菊花賞は3番人気で、三冠のかかったメイズイが道中で行きたがって馬群に沈むなか、直線で抜け出したコウライオーを差し切った。この勝利で厩舎は同じ年の牡馬クラシック三競走をすべて勝った。暮れの有馬記念は7着に大敗し、脚部不安で2年近く休んだ。復帰後のオープン戦ではシンザンにクビ差の3着だった。1966年の京王杯スプリングハンデキャップを勝ち、新潟の1600メートルでレコードも出している。1968年2月の中京まで走った。種牡馬としては産駒に恵まれず、血を引く馬はもう残っていない。' },
 { name:'ヤマトキヨウダイ', years:'1962〜1965年', record:'38戦12勝', mainWins:['1964 日本経済賞','1964 目黒記念（秋）','1964 天皇賞（秋）','1964 有馬記念'],
   text:'父ヒンドスタンの牡馬。1962年10月に東京の新馬戦でデビューし、9番人気で2着に入った。翌月の未勝利戦で初勝利を挙げた。1963年はオールカマーやカブトヤマ記念などの重賞に出たが勝てなかった。1964年に入っても金杯で5着、中山記念で3着と勝ち切れなかった。中1週で出た日本経済賞で初めて重賞を勝つと、秋は目黒記念で、のちの天皇賞馬アサホコとの競り合いを制した。天皇賞（秋）は2番人気で、1番人気のメイズイなどを寄せ付けず、3分21秒7のレコードで勝った。暮れの有馬記念は3番人気で、牝馬トーストを抑えて八大競走を2連勝した。この年の最優秀5歳以上牡馬に選ばれている。1965年は目黒記念と有馬記念でシンザンに敗れ、有馬記念の5着を最後に引退した。種牡馬としては目立つ産駒を出せなかった。甥に1966年の朝日杯3歳ステークスを勝ったモンタサンがいる。' },
 { name:'カネケヤキ', years:'1963〜1965年', record:'16戦6勝', mainWins:['1963 朝日盃3歳ステークス（2着）','1964 桜花賞','1964 優駿牝馬'],
   text:'1963年10月に中山でデビューした牝馬。朝日盃3歳ステークスは1番人気に推されたが、ウメノチカラにアタマ差及ばず2着だった。1964年は京成杯で6着、弥生賞で4着と牡馬相手に敗れた。桜花賞は4番人気で、先行して抜け出しフラミンゴに2馬身差をつけて勝った。東京の4歳牝馬特別を勝ってから臨んだオークスでは、ヤマニンルビーに3馬身差をつけて牝馬二冠を果たした。秋は脚部不安で調子を落とし、クイーンステークス2着、セントライト記念3着と勝てなかった。シンザンが三冠に挑んだ菊花賞では12頭立ての9番人気から大逃げを打ち、4コーナーまで粘って5着に残った。翌年のオープン戦を1つ走って引退した。繁殖では目立つ仔を出せなかったが、孫のカネミカサが中山記念を2度勝った。1995年に34歳で生涯を閉じ、そのころのサラブレッドの長寿記録を持っていた。' },
 { name:'ウメノチカラ', years:'1963〜1966年', record:'27戦9勝', mainWins:['1963 朝日盃3歳ステークス','1964 NHK盃','1964 東京優駿（2着）','1964 セントライト記念','1965 毎日王冠','1966 天皇賞（春）（2着）'],
   text:'1963年の朝日盃3歳ステークスを勝ち、この年の最優秀3歳牡馬に選ばれた。2着のカネケヤキとはアタマ差だった。1964年はスプリングステークスでシンザンと初めて戦い、3着に敗れた。皐月賞は4番人気で3着だった。トライアルのNHK盃を勝って臨んだ東京優駿では、直線で一度シンザンを交わしたが差し返され、1馬身4分の1差の2着に終わった。秋はセントライト記念をレコードで勝った。菊花賞は1番人気に推され、直線で先頭に立ったものの、シンザンに交わされて2馬身半差の2着だった。三冠馬の好敵手と呼ばれた。有馬記念のファン投票ではシンザンより多くの票を集めたが、本番は4着だった。1965年は新潟記念と毎日王冠を勝った。1966年の天皇賞（春）はハクズイコウの2着で、これが最後のレースになった。種牡馬としては人気が出ず、1978年に登録を抹消された。' },
 { name:'エイトクラウン', years:'1964〜1967年', record:'27戦10勝', mainWins:['1964 阪神3歳ステークス','1966 鳴尾記念','1966 宝塚記念'],
   text:'1964年8月にデビューした栗毛の牝馬。4戦目の野地菊特別を勝ち、阪神3歳ステークスをそれまでのレコードを1秒以上縮めて圧勝した。この年の最優秀3歳牝馬に選ばれ、翌年の初戦も勝って5連勝した。1965年の桜花賞は1番人気だったが、逃げたハツユキを捉えられず4着に終わった。オークスは16着、牡馬に混じった菊花賞も17着と大敗した。1966年は6月に鳴尾記念を勝ち、続く宝塚記念を制した。牝馬が宝塚記念を勝ったのはこれが初めてで、2005年のスイープトウショウまでほかにいなかった。この年の最優秀5歳以上牝馬にも選ばれている。1967年1月のオープン戦で2着に入り、これを最後に引退した。繁殖に入って産んだナオキが1975年の宝塚記念を勝ち、母子で同じレースを制した。1973年生まれのクラウンピラードは天皇賞で春秋とも2着になった。' },
 { name:'カブトシロー', years:'1964〜1968年', record:'69戦14勝', mainWins:['1965 カブトヤマ記念','1966 有馬記念（2着）','1967 天皇賞（春）（2着）','1967 天皇賞（秋）','1967 有馬記念'],
   text:'1964年7月に福島の新馬戦でデビューし、5年で69戦を走った。1965年は皐月賞で12着、東京優駿で5着に終わった。1966年の有馬記念は7番人気で、コレヒデにわずかに届かず2着だった。1967年の天皇賞（春）は最後方から追い込み、スピードシンボリに僅差の2着だった。秋の天皇賞（秋）は14頭立ての8番人気で、出遅れて最後方から進んだ。4コーナーで内ラチ沿いを抜け出し、ネイチブランナーに2馬身差をつけた。暮れの有馬記念は4番人気で、2周目の向正面から動いて先頭に立ち、リユウフアーロスに6馬身差をつけた。当時のこのレースで最大の着差だった。人気になると凡走し、人気が落ちると好走したため「新聞の読める馬」と呼ばれた。1968年の有馬記念の10着を最後に引退した。種牡馬としては大阪杯とマイラーズカップのゴールドイーグルを出した。1981年に廃用の話が出たが、ファンの嘆願で功労馬として余生を送った。' },
 { name:'キーストン', years:'1964〜1967年', record:'25戦18勝', mainWins:['1965 弥生賞','1965 京都盃','1965 東京優駿','1965 菊花賞（2着）','1966 金杯'],
   text:'1964年7月に函館でデビューした逃げ馬。1965年の弥生賞を1番人気で3馬身差で勝ったが、スプリングステークスではダイコーターに0.3秒差の2着に敗れ、初めて土がついた。皐月賞は2番人気で19番枠から逃げたものの、前走から14キロ減った馬体で失速し14着に沈んだ。東京優駿は不良馬場のなか2番枠から逃げ切り、1番人気のダイコーターに1馬身4分の3差をつけた。菊花賞もダイコーターと競り合い、ゴール前で交わされて0.1秒差の2着だった。1966年は金杯を勝ったが、大阪杯7着、天皇賞（春）5着と大きいレースでは勝てなかった。1967年12月の阪神大賞典は5頭立ての1番人気で逃げたが、直線でスパートした直後に左前脚を脱臼した。前のめりに崩れて鞍上が落馬し、頭を打って気を失った。馬は一度倒れてから立ち上がり、3本の脚で鞍上のそばへ戻ったとされる。そのまま予後不良と診断され、安楽死の措置がとられた。' },
 { name:'コレヒデ', years:'1965〜1967年', record:'29戦14勝', mainWins:['1966 東京新聞杯','1966 アルゼンチンジョッキークラブカップ','1966 天皇賞（秋）','1966 有馬記念','1967 ダイヤモンドステークス'],
   text:'1965年1月に新馬戦でデビューして2連勝した。クラシックは弥生賞とスプリングステークスで大敗し、皐月賞は出走の条件を満たせず出られなかった。東京優駿は17着、菊花賞は8着に終わった。1966年2月の東京新聞杯で1番人気のカブトシローを破って初めて重賞を勝ち、5月にはアルゼンチンジョッキークラブカップも制した。秋の天皇賞（秋）は2番人気で、2周目の2コーナーで先頭に立ちそのまま押し切った。暮れの有馬記念も2番人気で、逃げるヒシマサヒデを追って直線で抜け出し、カブトシローとスピードシンボリを振り切った。この勝利で当時の年間獲得賞金の記録を塗り替え、年度代表馬に選ばれた。1967年はダイヤモンドステークスでカブトシローを抑えて勝ったが、12月に引退した。半兄に1963年の天皇賞（春）を勝ったコレヒサがいる。種牡馬としては目立つ産駒を出せなかった。' },
 { name:'ダイコーター', years:'1964〜1968年', record:'30戦13勝（障害4戦1勝を含む）', mainWins:['1965 きさらぎ賞','1965 スプリングステークス','1965 NHK盃','1965 神戸杯','1965 菊花賞'],
   text:'1964年10月に京都の新馬戦でデビューし、2着に大差をつけて勝った。1965年はきさらぎ賞を勝ち、スプリングステークスでは1番人気のキーストンを捉えて勝った。皐月賞は1番人気だったが、8番人気のチトセオーにクビ差及ばず2着だった。NHK盃を勝って臨んだ東京優駿も1番人気に推された。直前に馬主が変わり、その値段が話題になった。不良馬場のなかキーストンに逃げ切られ、1馬身4分の3差の2着に敗れた。秋は神戸杯を勝ち、菊花賞では1番人気で逃げるキーストンを終始マークして、ゴール前の追い比べで交わした。その後は喘鳴症を患い、阪神大賞典でチトセオーに大敗し、天皇賞（春）も9着だった。障害にも出て1勝を挙げ、1968年5月の淀障害ステークス2着が最後のレースになった。種牡馬としてはニシノライデンやキタノリキオーなどを出し、1981年には種牡馬ランキングの4位に入った。' },
 { name:'チトセオー', years:'1965〜1967年', record:'24戦5勝', mainWins:['1965 皐月賞','1965 阪神大賞典','1965 京都記念（秋）（2着）'],
   text:'父ジルドレの栗毛の牡馬で、1965年1月に京都の新馬戦でデビューして3着だった。若葉賞を勝って臨んだ皐月賞は8番人気だった。2番人気のキーストンが直線で失速するなか、1番人気のダイコーターをクビ差しのいで勝った。続くNHK盃は15着に大敗し、東京優駿には出なかった。菊花賞も18頭立ての15着に終わった。秋の京都記念（秋）は前年の天皇賞（春）の勝ち馬ヒカルポーラにハナ差の2着に入った。暮れの阪神大賞典ではダイコーターらを抑えて勝ち、これが最後の重賞勝ちになった。1966年は9戦して3着にも入れず、天皇賞（春）は13着だった。1967年は4戦して1勝し、10月の京都の条件戦で4着になって引退した。種牡馬になったが目立つ産駒は出なかった。' },
 { name:'ベロナ', years:'1964〜1966年', record:'21戦7勝', mainWins:['1965 優駿牝馬','1965 日本短波賞'],
   text:'1964年7月に小倉でデビューした牝馬。小倉3歳特別をレコードで勝ち、宝塚3歳ステークスまで3連勝した。阪神3歳ステークスは3着だった。1965年の桜花賞は2番人気だったが、12着と初めて大きく負けた。このあと馬主が変わり、東京の厩舎へ移ってオークスに臨んだ。本命と見られた桜花賞馬ハツユキが出ず、4番人気でスタートから逃げた。そのまま粘り切り、ベストルーラーに半馬身差をつけて勝った。1番人気のビユーテイロツクは9着、エイトクラウンは16着だった。続く日本短波賞も勝ち、この年の最優秀4歳牝馬に選ばれた。秋はクイーンステークス2着のあと、セントライト記念で大敗した。1966年は勝ち星から遠ざかったが、9月の東京のオープンで1年ぶりに勝った。11月の天皇賞（秋）のレース中に故障して競走を中止し、予後不良となった。' },
 { name:'ニホンピローエース', years:'1965〜1968年', record:'24戦10勝', mainWins:['1965 阪神3歳ステークス','1966 皐月賞','1967 阪急杯'],
   text:'1965年10月に京都の新馬戦でデビューし、2着のリュウファーロスに約1.5秒の差をつけた。暮れの阪神3歳ステークスで初めて重賞を勝ち、この年の最優秀3歳牡馬に選ばれた。1966年は弥生賞で1番人気ながらタマシユウホウの2着、スプリングステークスも4着に敗れた。皐月賞は2番人気で、スタートから先頭に立って逃げた。1番人気のシヨウグンの追撃を半馬身しのいで勝った。そのあとはNHK杯5着、東京優駿は2番人気で20着、菊花賞も17着と崩れた。1967年の阪急杯をレコードで勝ち、皐月賞以来の重賞勝ちを挙げた。鳴尾記念でも2着に入ったが、函館記念を取り消して休んだ。1968年はオープンで1勝し、天皇賞（春）の4着を最後に引退した。種牡馬としては1979年の関屋記念を勝ったスズホープを出した。' },
 { name:'ワカクモ', years:'1965〜1969年', record:'53戦11勝', mainWins:['1966 桜花賞','1966 小倉記念'],
   text:'1965年10月に京都でデビューした牝馬で、初戦は14頭立ての12着だった。2戦目で勝ち上がった。1966年の桜花賞は4番人気で、1番人気は関東のメジロボサツだった。内を突いて抜け出し、ヒロヨシにクビ差、メジロボサツにはさらにハナ差の接戦を制した。母クモワカが2着に敗れたレースを娘が勝った。オークスは2番人気だったが、ヒロヨシの逃げを捉えられず7着に終わった。夏は小倉記念を7頭立ての4番人気で勝ち、筑紫賞では1800メートルのレコードを出した。その後も長く走り、のちに小倉で自分のレコードを0.2秒縮めている。1969年11月の京都牝馬特別を最後に、53戦11勝で引退した。気性は荒かったとされる。繁殖に入ってテンポイントと、中山大障害を春秋連覇したキングスポイントを産んだ。2頭は子孫を残さずにこの世を去ったが、娘たちから血が続いている。' },
 { name:'ヒロヨシ', years:'1965〜1967年', record:'13戦5勝', mainWins:['1966 桜花賞（2着）','1966 優駿牝馬'],
   text:'父ガーサントの牝馬で、1965年12月に中山でデビューし、9番人気で2着に入った。そこから1966年1月の東京のオープンまで3連勝した。桜花賞は7番人気だったが、ワカクモにクビ差の2着に入った。オークスは雨で不良馬場になり、5番人気だった。スタートから先頭に立って逃げ続け、1番人気のメジロボサツに9馬身差をつけて勝った。桜花賞で敗れたワカクモは7着だった。秋は牡馬に混じって菊花賞に挑み、10番人気で13着に終わった。翌1967年は古馬の牡馬を相手に走り、アメリカジョッキークラブカップで4着に入った。2月の東京のオープンを勝って引退した。デビューから引退まで同じ騎手が手綱をとった。繁殖では5頭の仔を残したが、目立つ活躍馬は出なかった。' },
 { name:'ニットエイト', years:'1966〜1969年', record:'36戦8勝', mainWins:['1967 菊花賞','1968 天皇賞（秋）'],
   text:'父ガーサントの牡馬。大きな流星と荒い気性から「白面の荒法師」と呼ばれた。1966年11月の新馬戦でデビューして勝った。1967年夏の函館では、斤量に恵まれて東京優駿の勝ち馬キーストンを破り、レコードで勝っている。秋はセントライト記念でモンタサンの2着に入った。菊花賞は重馬場で9番人気だった。同じ厩舎のリュウズキが先に抜け出したところを追い、1馬身半差をつけて交わした。1968年は天皇賞（秋）の前まで1勝しかできなかった。その天皇賞（秋）は6番人気で、1番人気のフイニイを1馬身4分の1突き放し、3分20秒3のレコードで勝った。1969年の有馬記念の5着を最後に、36戦8勝で引退した。ガーサントの後継として種牡馬になったが、宮崎、鹿児島、北海道と移っても成績は上がらなかった。13歳のとき肺炎のため天国へ旅立った。' },
 { name:'ヒカルタカイ', years:'1966〜1969年', record:'31戦15勝（うち中央11戦3勝）', mainWins:['1966 全日本三才優駿','1967 羽田盃','1967 東京ダービー','1967 東京王冠賞','1968 天皇賞（春）','1968 宝塚記念'],
   text:'1966年に大井でデビューし、2戦目のダート1000メートルを1分0秒2のレコードで走った。暮れの全日本三才優駿を勝った。1967年は羽田盃、東京ダービー、東京王冠賞を勝ち、三冠の競走ができてから初めての南関東三冠馬になった。暮れの東京大賞典は2着だった。脚部不安があり、買われたときの値段は70万円と安かった。1968年に中央へ移り、オープンで3戦続けて2着になった。重馬場の天皇賞（春）は1番人気で、2着のタイヨウに2.8秒の大差をつけて勝った。17馬身とも18馬身とも言われ、八大競走で最大の着差とされる。続く宝塚記念は2分14秒7のレコードで勝ち、雨に助けられたという声を打ち消した。この年の最優秀古馬牡馬に選ばれた。1969年12月のオープン戦の6着を最後に引退した。種牡馬としては目立たなかったが、母の父として桜花賞のダイアナソロンを出した。' },
 { name:'リュウズキ', years:'1966〜1970年', record:'35戦14勝', mainWins:['1967 皐月賞','1967 函館記念','1967 菊花賞（2着）','1968 函館記念','1968 有馬記念'],
   text:'1966年6月に函館の新馬戦でデビューした青毛の牡馬。1967年の皐月賞は3番人気で、好位から早めに動いて4コーナーの手前で先頭に立った。そのまま押し切り、ホウゲツオーに2馬身半差をつけた。東京優駿は1番人気だったが、アサデンコウの5着に敗れた。夏は函館記念を勝った。菊花賞は2番人気で先頭に立ったものの、同じ厩舎のニットエイトに1馬身半差で交わされて2着だった。この年の最優秀4歳牡馬に選ばれた。1968年は函館記念を61キロでレコード勝ちして連覇した。天皇賞（秋）は2番人気で9着に沈んだ。暮れの有馬記念は6番人気で、不良馬場を先行して押し切り、ニウオンワードに2馬身半差をつけた。1969年の有馬記念は15着に終わり、1970年7月の札幌記念の6着を最後に引退した。種牡馬としてはカブトヤマ記念のリュウフブキを出した。' },
 { name:'アサカオー', years:'1967〜1970年', record:'24戦8勝', mainWins:['1968 弥生賞','1968 日本短波賞','1968 セントライト記念','1968 菊花賞','1969 アメリカジョッキークラブカップ'],
   text:'1967年10月に中山でデビューした。朝日杯3歳ステークスはタケシバオーに1秒2離された3着だった。1968年は弥生賞で、飛ばしていくタケシバオーの後ろで待ち、直線で抜け出して初めて重賞を勝った。マーチス、タケシバオーとともに「三強」と呼ばれた。皐月賞は3番人気でマーチスの3着、東京優駿も3番人気で逃げ切ったタニノハローモアの3着に終わった。夏の日本短波賞ではマーチスをハナ差抑え、秋はセントライト記念も勝った。タケシバオーが出なかった菊花賞は2番人気で、後方から追い込んでダテホーライに1馬身4分の1差をつけた。マーチスは3着だった。この年の年度代表馬に選ばれた。有馬記念は1番人気だったが、不良馬場で伸びず6着だった。1969年はアメリカジョッキークラブカップを勝ち、天皇賞（春）はタケシバオーの2着だった。1970年に戻ってから4戦勝てず引退した。種牡馬としては産駒が46頭と少なく、活躍馬は出なかった。' },
 { name:'マーチス', years:'1967〜1970年', record:'31戦14勝', mainWins:['1967 阪神3歳ステークス','1968 スプリングステークス','1968 皐月賞','1968 NHK盃','1969 目黒記念（秋）'],
   text:'1967年7月に函館の新馬戦でデビューした。31戦のうち21戦で1番人気に推され、4番人気より下になったことは一度もない。暮れの阪神3歳ステークスは2番人気で、後方で脚をためて差し切った。1968年はタケシバオー、アサカオーとともに「三強」と呼ばれた。弥生賞はアサカオーの3着だったが、スプリングステークスでは2頭を破った。馬インフルエンザで5月にずれた皐月賞は雨の重馬場で、最後方から押し上げた。直線で競り合うタケシバオーとアサカオーを外から交わし、4分の3馬身差で勝った。7月の東京優駿は1番人気だったが、20番枠と道中の不利があり、逃げたタニノハローモアの4着に敗れた。NHK盃や札幌記念を勝ったものの、菊花賞も1番人気でアサカオーの3着だった。この年の最優秀4歳牡馬に選ばれた。古馬になってからは宝塚記念2着が最高で、天皇賞と有馬記念は勝てなかった。1970年4月のオープン戦を勝って引退し、種牡馬になったが目立つ産駒は出なかった。' },
 { name:'タニノハローモア', years:'1967〜1969年', record:'30戦9勝', mainWins:['1968 京都盃','1968 東京優駿','1968 朝日チャレンジカップ','1969 中京記念'],
   text:'1967年8月にデビューしたが、初勝利までに4戦かかった。東京優駿までに17戦を走り、11月のオープンをレコードで勝つなど5勝を挙げたが、重賞は勝てなかった。1968年の皐月賞はマーチスの6着、NHK盃も3着に敗れた。馬インフルエンザで7月にずれた東京優駿は8連敗中で、9番人気の評価だった。1枠1番から逃げると、マーチス、タケシバオー、アサカオーの「三強」が互いに牽制し合った。そのまま逃げ切り、2着のタケシバオーに5馬身差をつけた。ダービーの約1か月後には札幌記念に出て、秋は京都盃と朝日チャレンジカップを勝った。菊花賞は6着だった。30戦のうち5着より下に沈んだのは皐月賞と菊花賞の2度だけだった。1969年の中京記念を勝ち、春に引退した。展開に恵まれた勝利と見られたため種牡馬としての評価は低く、目立つ産駒は出なかった。' },
 { name:'トウメイ', years:'1968〜1971年', record:'31戦16勝', mainWins:['1969 京都4歳特別','1970 マイラーズカップ','1971 マイラーズカップ','1971 阪急杯','1971 天皇賞（秋）','1971 有馬記念'],
   text:'1968年8月に札幌の新馬戦でデビューした牝馬。1969年3月の京都4歳特別で初めて重賞を勝った。桜花賞はゴール前でヒデコトブキに交わされて2着、オークスはライトパレーの3着だった。古馬になるとマイラーズカップを2年続けて勝ち、「マイルの女王」と呼ばれた。1971年は阪急杯を58キロ、東京タイムズ杯を59キロのトップハンデで勝った。天皇賞（秋）は3番人気で、菊花賞馬アカネテンリュウやダービー馬ダイシンボルガードを下した。馬体重428キロは天皇賞の勝ち馬で最も軽い。暮れの有馬記念は馬インフルエンザで取消が相次ぎ、6頭立てになった。最後方から進み、4コーナーで先頭に立って押し切った。この年の年度代表馬に選ばれ、これが最後のレースになった。繁殖では14頭の仔を産み、テンメイが1978年の天皇賞（秋）を勝って初めての天皇賞母子制覇になった。' },
 { name:'アカネテンリュウ', years:'1968〜1972年', record:'36戦13勝', mainWins:['1969 セントライト記念','1969 菊花賞','1970 日本経済賞','1971 アメリカジョッキークラブカップ','1971 目黒記念（秋）','1972 東京新聞杯'],
   text:'春のうちは条件馬だったが、1969年夏の函館から勝ち続け、「戦後最大の上がり馬」と呼ばれた。秋はセントライト記念を勝ち、菊花賞は1番人気に推された。直線で内へ外へと大きく蛇行しながらも、2着のリキエイカンに4馬身差をつけて勝った。暮れの有馬記念は3番人気で、スピードシンボリにハナ差まで迫って2着だった。1970年は日本経済賞を勝った。有馬記念はまたスピードシンボリにクビ差の2着で、3着のダテテンリュウともハナ差の叩き合いだった。道悪が得意で、60キロを超える斤量でオープンを3度勝っている。古馬になって天皇賞に4度挑んだが、リキエイカン、メジロアサマ、トウメイと同期の馬に先を越された。1972年の天皇賞（春）の3着を最後に引退した。種牡馬としては条件戦を勝つ産駒を出すにとどまった。' },
 { name:'メジロアサマ', years:'1968〜1972年', record:'48戦17勝', mainWins:['1970 安田記念','1970 函館記念','1970 天皇賞（秋）','1971 ハリウッドターフクラブ賞','1972 アメリカジョッキークラブカップ'],
   text:'1968年7月に函館でデビューした芦毛の牡馬。2戦目から3連勝したが、重賞は勝てずローカルの開催を転戦した。1969年の東京優駿は16着に大敗した。1970年に厩舎を移ってから力を出し始め、5月の安田記念で初めて重賞を勝ち、9月には函館記念も制した。3200メートルは長いと見られていた天皇賞（秋）は5番人気で、フイニイの追撃を半馬身退けた。芦毛の馬が天皇賞を勝ったのはこれが初めてだった。1971年は宝塚記念で僚馬メジロムサシの2着に入り、秋はハリウッドターフクラブ賞を勝った。有馬記念は馬インフルエンザで出られなかった。1972年はアメリカジョッキークラブカップをレコードで勝ち、暮れの有馬記念でイシノヒカルの2着になって引退した。種牡馬入りした最初の年は、病気の治療で使った薬の影響もあって受胎した牝馬がいなかった。それでも治療を続けて19頭の産駒を残し、そのうちのメジロティターンが天皇賞を勝った。その仔メジロマックイーンも天皇賞を勝ち、父子三代の天皇賞馬になった。' },
 { name:'リキエイカン', years:'1968〜1972年', record:'48戦13勝', mainWins:['1968 阪神3歳ステークス','1969 菊花賞（2着）','1970 スワンステークス','1970 天皇賞（春）'],
   text:'父ネヴァービートの牡馬で、1968年に札幌の新馬戦でデビューして勝った。6戦2勝で出た阪神3歳ステークスでは、のちの桜花賞馬ヒデコトブキらを破って勝った。1969年の皐月賞は16着、東京優駿は4着だった。夏の札幌記念では古馬に混じってマーチスの2着に入った。菊花賞はアカネテンリュウに4馬身離された2着だった。1970年の天皇賞（春）は阪神で行われ、2番人気だった。逃げたホウウンを直線で捉え、追い込むフイニイをクビ差抑えてレコードで勝った。菊花賞で敗れたアカネテンリュウにも先着した。その後は1971年の函館記念と札幌記念の2着が重賞での最高で、オープンの勝ちにとどまった。1972年に引退して種牡馬になったが活躍馬は出せず、1980年に用途を変えられた。生まれた牧場に引き取られて余生を送り、2001年に35歳で永眠した。' },
 { name:'タニノムーティエ', years:'1969〜1970年', record:'18戦12勝', mainWins:['1969 阪神3歳ステークス','1970 スプリングステークス','1970 弥生賞','1970 皐月賞','1970 東京優駿'],
   text:'1969年7月に函館でデビューした栗毛の牡馬。暮れの阪神3歳ステークスは1番人気で、先行馬を大外から差し切った。1970年は関東のアローエクスプレスとの対決が「A・T対決」と呼ばれて沸いた。スプリングステークスでは10馬身ほどあった差を詰めて捉え、初めて相手に勝った。NHK杯は鞍上がゴールを誤って早めに追うのをやめ、アローエクスプレスに2馬身半差で敗れた。皐月賞は1番人気で、重馬場のなかアローエクスプレスをアタマ差抑えた。東京優駿は2番人気で中団から伸び、ダテテンリュウに半馬身差をつけて二冠を果たした。夏に喘鳴症を患い、秋は朝日チャレンジカップ8着、京都盃6着と崩れた。三冠のかかった菊花賞は5番人気で11着に終わり、このレースを最後に引退した。種牡馬としては京都3歳ステークスのタニノサイアスなどを出した。半弟に天皇賞（秋）と有馬記念を勝ったタニノチカラがいる。' },
 { name:'タマミ', years:'1969〜1971年', record:'24戦8勝', mainWins:['1970 クイーンカップ','1970 桜花賞','1970 阪神4歳牝馬特別','1970 スプリンターズステークス','1971 京王杯スプリングハンデキャップ'],
   text:'1969年8月に東京の新馬戦でデビューした快速の牝馬で、「美少女」と呼ばれて人気を集めた。1970年はクイーンカップを勝って桜花賞に臨み、1番人気に応えた。スタートから先頭に立ち、2着のスターウイングに4馬身差をつけて逃げ切った。オークスも1番人気だったが、不良馬場と長い距離に苦しみ14着に大敗した。秋は最優秀4歳牝馬に選ばれたハーバーゲイムに2度敗れた。暮れのスプリンターズステークスは苦手の不良馬場だったが、逃げてハナ差で粘り切った。最初の3ハロンを33秒9で走り、のちにサクライワイが出るまで最も速い記録だった。1971年の京王杯スプリングハンデキャップを勝ち、7月の函館の巴賞で3着になって引退した。繁殖牝馬になったが目立つ産駒は出ず、1977年に11歳でこの世を去った。血統は曾孫の代で途絶えた。' },
 { name:'メジロムサシ', years:'1969〜1973年', record:'36戦10勝（中央34戦10勝・海外2戦0勝）', mainWins:['1971 目黒記念（春）','1971 天皇賞（春）','1971 宝塚記念','1971 函館記念','1973 ハリウッドターフクラブ賞（2着）'],
   text:'1969年7月にデビューした黒鹿毛の牡馬。気性が激しく、晩成でもあり、3歳の秋はセントライト記念2着、菊花賞4着と重賞に手が届かなかった。1971年の目黒記念（春）で初めて重賞を勝ち、僚馬メジロアサマが2着に入った。天皇賞（春）は大雨で不良馬場になり、2番人気だった。直線でオオクラとの叩き合いになり、クビ差で競り勝った。続く宝塚記念は3番人気で、1番人気のメジロアサマをクビ差抑えた。夏の函館記念も62キロのトップハンデで勝ち、この年の最優秀5歳以上牡馬に選ばれた。暮れの有馬記念は6頭立ての1番人気だったが5着に終わった。1972年は海外へ渡り、凱旋門賞で18着、ワシントンDCインターナショナルで7着と振るわなかった。帰国後は勝てず、1973年のハリウッドターフクラブ賞でタニノチカラの2着に入り、12月のクモハタ記念を最後に引退した。種牡馬としてはアングロアラブの最優秀馬ライトオスカーを出した。' },
 { name:'ヤマニンウエーブ', years:'1970〜1974年', record:'48戦10勝', mainWins:['1972 平安ステークス','1972 京都記念（秋）','1972 天皇賞（秋）','1974 日本経済新春杯（2着）'],
   text:'1970年2月にデビューした黒鹿毛の牡馬。1971年は特別戦など4勝を挙げたが、重賞では届かなかった。1972年は平安ステークスなどを勝ち、京都記念（秋）で初めて重賞を制した。この年は朝日チャレンジカップと阪神大賞典でも2着に入っている。続く天皇賞（秋）は15頭立ての7番人気だった。スタート直後に1頭が落馬し、パッシングゴールが大逃げを打って、2周目の向正面では30馬身以上のリードを取った。14番手にいたヤマニンウエーブは向正面から1000メートル近いロングスパートをかけ、ゴール寸前でクビ差捉えた。枠連は1万210円で、天皇賞で初めての万馬券になった。この年の最優秀5歳以上牡馬に選ばれた。その後は勝てなかったが、1974年の日本経済新春杯まで重賞で4度2着に入った。種牡馬としては3年で28頭の産駒を残し、1978年に放牧中の骨折により生涯を閉じた。' },
 { name:'ヒカルイマイ', years:'1970〜1971年', record:'15戦7勝', mainWins:['1971 きさらぎ賞','1971 皐月賞','1971 NHK杯','1971 東京優駿'],
   text:'父シプリアニの牡馬で、1970年10月に京都の新馬戦を5馬身差で勝った。京都3歳ステークスは2着、スプリングステークスは4着だったが、1971年のきさらぎ賞で初めて重賞を勝った。馬インフルエンザで5月にずれた皐月賞は4番人気で、後方から追い込み、バンライに1馬身4分の3差をつけた。NHK杯もダコタにクビ差で勝った。28頭立ての東京優駿は2番人気で、1コーナーでは23番手あたりにいた。直線だけで20頭あまりを交わし、ハーバーローヤルに1馬身4分の1差をつけて二冠を果たした。秋は札幌で3着、京都新聞杯で9着と敗れ、菊花賞の前に屈腱炎を発症した。2年ほど休んだが戻れずに引退した。種牡馬としては人気が出ず、一時は種付けが途絶えた。鹿児島の牧場に移り、ファンの会が支えて余生を送った。' },
 { name:'アチーブスター', years:'1971〜1973年', record:'32戦4勝', mainWins:['1972 桜花賞','1972 ビクトリアカップ'],
   text:'父シプリアニの黒鹿毛の牝馬。1971年9月に阪神の新馬戦でデビューして7着だった。1972年はトライアルの阪神4歳牝馬特別で4着に入り、桜花賞の出走権を得た。馬インフルエンザで5月にずれた桜花賞は8番人気だった。キョウエイグリーンが速いペースで逃げるなか、後方の内に控えて直線で抜け出し、ハジメローズに3馬身差をつけた。単勝2890円は当時の桜花賞で2番目の高配当だった。クラシックの登録がなくオークスには出られなかった。秋はサファイヤステークス7着、京都牝馬特別9着と負けが続いた。ビクトリアカップは5番人気で、1番人気のタカイホーマが競走を中止するなか、タイラップをクビ差抑えて勝った。この年の最優秀4歳牝馬にトクザクラと並んで選ばれた。1973年11月の京都記念の4着を最後に引退した。繁殖ではオープン勝ちのワンダービクトリーやワンダーヒロインを出した。' },
 { name:'イシノヒカル', years:'1971〜1973年', record:'15戦7勝', mainWins:['1972 皐月賞（2着）','1972 菊花賞','1972 有馬記念'],
   text:'1971年9月に中山の新馬戦でデビューして5着だった。同じ年の生まれにはロングエース、タイテエム、ランドプリンスらがいて、「花の47年組」と呼ばれた。1972年の皐月賞は4番人気で、後方から追い込んだがランドプリンスにわずかに届かず2着だった。東京優駿は27頭立ての23番枠から馬群をさばけず、ロングエースの6着に終わった。日本短波賞も1番人気でスガノホマレに差されて2着だった。菊花賞は連闘で臨み、重馬場を後方から追い込んで、1番人気のタイテエムを1馬身4分の1突き放した。暮れの有馬記念はファン投票1位で1番人気に推され、大外から伸びてメジロアサマを1馬身半抑えた。4歳の牡馬が有馬記念を勝ったのはこれが初めてだった。この年の年度代表馬に選ばれた。翌1973年は11月の東京のオープンで7着に敗れたのが最後のレースになった。種牡馬としては交配の相手に恵まれず、中央の勝ち馬を数頭出すにとどまった。' },
 { name:'タイテエム', years:'1971〜1973年', record:'16戦8勝', mainWins:['1972 スプリングステークス','1972 東京優駿（3着）','1972 京都新聞杯','1973 マイラーズカップ','1973 天皇賞（春）'],
   text:'1971年10月にデビューし、初戦は1番人気で8着だった。気品のある姿から「貴公子」と呼ばれた。1972年はスプリングステークスで前年の最優秀3歳牡馬ヒデヤテを破った。皐月賞はランドプリンスに敗れた。馬インフルエンザで7月にずれた東京優駿は3番人気で、先頭に立ったところをロングエースとランドプリンスに交わされ、クビとアタマの差の3着だった。秋は神戸新聞杯と京都新聞杯を勝ち、菊花賞は1番人気に推されたが、直線でイシノヒカルに交わされて2着に終わった。クラシックを勝てなかったことから「無冠の貴公子」とも呼ばれた。1973年は不良馬場のマイラーズカップを5番人気で勝ち、天皇賞（春）は1番人気でカツタイコウに1馬身半差をつけて勝った。続く宝塚記念は1番人気だったが、逃げるハマノパレードにクビ差届かず2着だった。そのあと鐙が壊れて落馬したときにアキレス腱を傷め、秋に引退した。種牡馬としては八大競走の勝ち馬は出せなかった。' },
 { name:'タニノチカラ', years:'1971〜1975年', record:'24戦13勝', mainWins:['1973 朝日チャレンジカップ','1973 ハリウッドターフクラブ賞','1973 天皇賞（秋）','1974 有馬記念','1975 京都記念'],
   text:'タニノムーティエの半弟にあたる栗毛の牡馬。1971年9月に阪神でデビューしたが、10月の野菊賞のレース中に骨折した。翌年もダービーを目指す調教中に左前脚を骨折し、一時は予後不良とまで言われた。牧場で療養して1973年7月に戻った。若いころは兄と同じ追い込みだったが、鞍上が替わってから先行するようになった。この年は朝日チャレンジカップとハリウッドターフクラブ賞を勝ち、天皇賞（秋）は2番人気だった。残り1000メートルほどで先頭に立ち、ミリオンパラに2馬身差をつけて押し切った。有馬記念はハイセイコーをマークしたが仕掛けが遅れて4着だった。1974年の有馬記念は2番人気で、スタートから先頭に立ち、ハイセイコーに5馬身差をつけて雪辱した。1973年と1974年の最優秀5歳以上牡馬に選ばれた。1975年は京都記念を大差で勝ったが、マイラーズカップ3着のあと脚を傷めて引退した。種牡馬になって5年目、種付けの最中に倒れ、そのまま息を引き取った。' },
 { name:'ナオキ', years:'1971〜1975年', record:'30戦13勝', mainWins:['1973 中京記念','1975 中京記念','1975 宝塚記念','1975 鳴尾記念'],
   text:'母は宝塚記念を勝ったエイトクラウン。1971年8月に函館の新馬戦でデビューした。1973年の中京記念を逃げ切って初めて重賞を勝った。同じ年の宝塚記念はハマノパレードとタイテエムの競り合いに続く3着だった。天皇賞は春の4着が最高で、有馬記念も6着だった。1975年は金杯をレコードで勝ち、中京記念も2度目の勝利を挙げた。中京競馬場では7戦6勝だった。宝塚記念は2番人気で、スタートから逃げてモアーキヤツスルに2馬身半差をつけた。母に続いて宝塚記念を勝ち、母子で同じレースを制した。続く鳴尾記念もレコードで勝った。秋は京都記念11着、天皇賞（秋）7着に終わり、引退した。種牡馬としてはカブトヤマ記念のチェリーテスコを出したが、成績は振るわなかった。' },
 { name:'ロングエース', years:'1972年', record:'10戦6勝', mainWins:['1972 弥生賞','1972 皐月賞（3着）','1972 東京優駿'],
   text:'1972年1月にデビューし、新馬戦、ヒヤシンス賞、フリージア賞と3連勝した。オープンでランドプリンスを破り、弥生賞でも同じ相手を退けて5連勝で初めて重賞を勝った。同じ年の生まれは「花の47年組」と呼ばれ、ランドプリンス、タイテエムとともに三強に数えられた。皐月賞は1番人気だったが、ランドプリンスに先着されて3着だった。馬インフルエンザで7月にずれた東京優駿は「七夕ダービー」と呼ばれる。1番人気で、先頭に立ったタイテエムをランドプリンスが追い、内から3頭の競り合いになった。ランドプリンスにクビ差、タイテエムにはさらにアタマ差をつけ、レコードで勝った。馬体重500キロを超える馬はダービーを勝てないという言い伝えもこれで破られた。秋は京都新聞杯6着、菊花賞5着、有馬記念8着と勝てず、イシノヒカルに屈して引退した。種牡馬としては宝塚記念のテルテンリュウを出し、日本で初めての白毛馬ハクタイユーの父にもなった。' },
 { name:'ハマノパレード', years:'1971〜1973年', record:'20戦8勝', mainWins:['1972 阪神大賞典','1973 京都記念（春）','1973 大阪杯（2着）','1973 宝塚記念'],
   text:'1971年11月にデビューした。10月に予定していた初戦は骨膜炎で取り消している。1972年は春の毎日杯で9着だったが、暮れの阪神大賞典でヤマニンウエーブらを破って初めて重賞を勝った。1973年は日本経済新春杯を重馬場で6着、京都記念（春）を勝ち、大阪杯はニホンピロムーテーの2着だった。天皇賞（春）は4コーナーでタイテエムと脚が触れ、8着に終わった。宝塚記念は8頭立ての4番人気で、スタートから先頭に立って速いペースで逃げた。直線で1番人気のタイテエムに並ばれたが、クビ差振り切り、2分12秒7のレコードで勝った。続く6月の高松宮杯は2番人気で、直線で抜け出したところ、ゴールの200メートルほど手前でつまずいて転倒した。左前脚の脱臼と骨折で予後不良と診断された。その日のうちに安楽死の措置がとられたとされるが、翌日に食肉処理場へ運ばれたとする証言もある。' },
 { name:'カミノテシオ', years:'1972〜1975年', record:'21戦5勝', mainWins:['1973 京成杯','1974 天皇賞（秋）'],
   text:'1972年9月に中山の新馬戦でデビューした。1973年の京成杯は1番人気で、ニューサントと並んでゴールし、写真判定でハナ差先着した。続く弥生賞のレース中に右前脚の球節を傷め、皐月賞は7着に終わった。東京優駿は直前の調教のあと歩様が乱れ、球節炎と診断されて出走を取り消し、そこから1年以上休んだ。復帰後は京王杯オータムハンデキャップと毎日王冠で3着、1番人気の目黒記念（秋）で2着と勝ちきれなかった。1974年の天皇賞（秋）は5番人気で、イチフジイサミを半馬身抑えて勝った。1977年に種牡馬となったが、内国産種牡馬が不遇の時代で、6年間の産駒は14頭にとどまった。その後は乗用馬となり、馬術の少年団の騎乗馬も務め、1996年に宇都宮の育成牧場で老衰のため永眠した。' },
 { name:'タケホープ', years:'1972〜1974年', record:'19戦7勝', mainWins:['1973 東京優駿','1973 菊花賞','1974 アメリカジョッキークラブカップ','1974 天皇賞（春）'],
   text:'1972年7月にデビューした。1973年の東京優駿は9番人気で外枠からの発走だったが、先頭が何度も入れ替わる速い流れを直線の終盤で抜け出し、イチフジイサミに1馬身3/4差をつけてレコードで勝った。1番人気のハイセイコーは3着だった。秋は京都新聞杯で8着に敗れ、菊花賞は6番人気にとどまった。前半の極端に遅い流れから最後はハイセイコーと並んでゴールし、写真判定でハナ差先着して二冠馬となった。この年の年度代表馬に選ばれた。1974年はアメリカジョッキークラブカップを最後方から差し切り、天皇賞（春）もストロングエイトをクビ差で捉えて勝った。引退レースの有馬記念は1番人気で3着に終わり、タニノチカラが逃げ切った。種牡馬としてはアルゼンチン共和国杯2着のミナガワローレルなどを出したが、大きな活躍馬は出ず、1994年にこの世を去った。' },
 { name:'ニットウチドリ', years:'1972〜1974年', record:'21戦6勝', mainWins:['1973 阪神4歳牝馬特別','1973 桜花賞','1973 ビクトリアカップ','1973 有馬記念（2着）'],
   text:'「女野武士」と呼ばれた先行の牝馬。1972年11月の未勝利戦を大差で逃げ切り、さざんか賞と新春4歳牝馬ステークスも勝った。1973年の阪神4歳牝馬特別はキシュウローレルをクビ差抑えてレコードで勝ち、桜花賞では1番人気に応えて同じ相手を3馬身突き放した。オークスは3コーナーから先頭で粘ったが、ナスノチグサに差されて2着だった。秋のビクトリアカップでは逃げ馬を捕らえ、そのナスノチグサに2馬身半差をつけて牝馬二冠を果たした。暮れの有馬記念は唯一の牝馬で7番人気だった。逃げて遅い流れを作り、ストロングエイトとの写真判定にクビ差で敗れて2着となり、このレースで初めての万馬券が出た。翌年は7戦すべて下位に終わり、引退した。繁殖では11頭の仔を産み、初仔エスパルは七夕賞で2着に入った。' },
 { name:'ホワイトフォンテン', years:'1972〜1976年', record:'50戦11勝', mainWins:['1975 日本経済賞','1975 毎日王冠','1976 アメリカジョッキークラブカップ','1976 日本経済賞'],
   text:'芦毛の逃げ馬で、父の名と毛色にちなんで「白い逃亡者」と呼ばれ、主戦騎手とのコンビで同期のハイセイコーと並ぶほどの人気を集めた。1972年秋にデビューし、新馬戦でのちの桜花賞馬ニットウチドリに勝った。1973年の東京優駿は先行したが24着に沈んだ。日本最長距離ステークスを逃げ切ったときは勝ち時計が遅く、このレースが廃止される一因になったとされる。1975年の日本経済賞をブービー人気で逃げ切って重賞初勝利を挙げ、毎日王冠も7番人気で逃げ切った。1976年はアメリカジョッキークラブカップをまたブービー人気で逃げ切り、日本経済賞も逃げて連覇した。先手を取れなかった天皇賞（秋）は最下位に終わった。引退レースに予定した1977年のアメリカジョッキークラブカップは本馬場入場前に左前脚を折って除外となり、そのまま引退した。種牡馬としては皐月賞5着のアサカフォンテンなどを出し、1996年に27歳で天国へ旅立った。' },
 { name:'アイフル', years:'1973〜1977年', record:'43戦12勝', mainWins:['1976 日刊スポーツ賞金杯','1976 アルゼンチン共和国杯','1976 天皇賞（秋）','1977 中山記念','1977 アルゼンチン共和国杯'],
   text:'1973年11月の新馬戦で3頭同着の1着となってデビューした。勝ちきれないレースも多く、43戦で2着が13回あった。1976年の金杯を中団から抜け出して重賞初勝利を挙げ、アルゼンチン共和国杯もクビ差で差し切った。同じ年の天皇賞（秋）は4番人気で、ロングホークが逃げるなか中団につけ、ハーバーヤングとの争いを制して1馬身3/4差で勝った。暮れの有馬記念はトウショウボーイの3着で、この年の最優秀5歳以上牡馬に選ばれた。1977年は中山記念を内から伸びて1馬身半差で勝ち、不良馬場のアルゼンチン共和国杯を3馬身半差で勝って連覇した。宝塚記念の4着を最後に屈腱炎で引退した。種牡馬としては良い産駒に恵まれず繋養先を転々としたが、ファンの声をきっかけに那須の種馬場へ移り、1999年に29歳で生涯を閉じた。' },
 { name:'キタノカチドキ', years:'1973〜1975年', record:'15戦11勝', mainWins:['1973 阪神3歳ステークス','1974 スプリングステークス','1974 皐月賞','1974 菊花賞','1975 読売杯マイラーズカップ'],
   text:'テスコボーイ産駒の先行馬で、スピードに優れていた。1973年9月にデビューして阪神3歳ステークスまで負けず、最優秀3歳牡馬に選ばれた。1974年はきさらぎ賞とスプリングステークスを勝ち、皐月賞は史上初めて単枠指定を受けて出走し、直線でコーネルランサーを抑えて勝った。東京優駿は19番枠から直線で内外によれて失速し、コーネルランサーの3着で初めて敗れた。秋は神戸新聞杯と京都新聞杯を勝ち、菊花賞は好位で折り合ってバンブトンオールを抑え、二冠を果たした。単勝120円は2005年まで菊花賞の最低配当だった。この年の年度代表馬に選ばれている。1975年はマイラーズカップを勝ったが、天皇賞（春）はイチフジイサミの2着だった。ファン投票1位の有馬記念はレース中に骨折して8着に終わり、引退した。種牡馬としてはトーワカチドキやマチカネイシンなどの重賞勝ち馬を出し、1983年に心臓発作のためこの世を去った。' },
 { name:'サクライワイ', years:'1973〜1975年', record:'26戦8勝', mainWins:['1973 函館3歳ステークス','1974 桜花賞（2着）','1974 読売杯スプリンターズステークス','1975 安田記念','1975 読売杯スプリンターズステークス'],
   text:'1973年8月のダートの新馬戦を勝ってデビューし、函館3歳ステークスを不良馬場で3馬身差で逃げ切った。1974年の桜花賞は1番人気で、直線で先頭に立ったが内から差されて3/4馬身差の2着だった。オークスも1番人気だったが距離が長く16着に大敗し、そこから短い距離に絞った。1200メートルのオープンをレコードで勝ち、スプリンターズステークスはそれまでの記録を1秒縮める1分8秒4の日本レコードで逃げ切った。1975年は安田記念まで7戦勝てなかったが、その安田記念を53キロの軽いハンデで6番人気ながら逃げ、アイアンロングに4馬身差をつけた。秋のスプリンターズステークスは4番手から直線でキャッシュボアをクビ差捉えて連覇した。このレースを連覇した牝馬はほかにメイワキミコしかいない。引退後は生まれた牧場で繁殖に入ったが、目立った仔は出ず、子孫は残っていない。' },
 { name:'トウコウエルザ', years:'1973〜1977年', record:'30戦5勝', mainWins:['1974 優駿牝馬','1974 クイーンステークス','1974 ビクトリアカップ'],
   text:'1973年11月にデビューしたが、初勝利は翌年2月で、クラシックが始まった時点では下級条件の馬だった。鞍上が替わって条件戦を勝ち、1974年のオークスに出た。前日発売では単勝1番人気だったが、当日は26頭立ての9番人気まで下がった。レースではスピードシンザンを競り落として勝ち、父パーソロンの産駒はオークスを4年続けて勝った。秋はクイーンステークスとビクトリアカップを続けて勝ち、最優秀4歳牝馬に選ばれた。古馬になると牝馬の路線がなく、牡馬を相手に中長距離を走った。1975年の京王杯オータムハンデキャップでは同じオークス馬ナスノチグサの2着に入った。1975年の天皇賞（秋）、1976年の宝塚記念と高松宮杯はいずれもフジノパーシアの3着で、1977年の金杯が最後のレースになった。繁殖では仔出しが悪く、牝系はひ孫の代で絶えた。1989年に天国へ旅立った。' },
 { name:'フジノパーシア', years:'1973〜1976年', record:'23戦11勝', mainWins:['1975 東京新聞杯','1975 天皇賞（秋）','1976 ダイヤモンドステークス','1976 宝塚記念','1976 高松宮杯'],
   text:'1973年冬のデビュー戦を勝ち、1975年2月の東京新聞杯で重賞初勝利を挙げた。同じ年の天皇賞（秋）は不良馬場で2番人気だった。中団から4コーナー手前でスパートして先頭に立ち、1番人気のキクノオーが伸びあぐねるなか、追ってくる同期の馬を抑えて勝った。1番人気の有馬記念は、逃げるホワイトフォンテンを意識しすぎたところをイシノアラシに突かれて2着に敗れた。ホワイトフォンテンとは相性が悪かったとされる。1976年はダイヤモンドステークス、京都で行われた宝塚記念、高松宮杯を勝った。秋は日本の代表としてワシントンDCインターナショナルに挑み、得意の不良馬場だったが、現地の騒がしさで落ち着きを欠いて6着だった。同じ年の有馬記念の8着を最後に引退した。種牡馬としては振るわず、晩年は当て馬を務め、1987年に腸捻転のため安楽死の措置がとられた。' },
 { name:'エリモジョージ', years:'1974〜1979年', record:'44戦10勝', mainWins:['1975 シンザン記念','1976 天皇賞（春）','1976 函館記念','1976 京都記念（秋）','1978 宝塚記念'],
   text:'「気まぐれジョージ」「愛しき反逆者」と呼ばれた。1974年8月にデビューし、白菊賞と1975年のシンザン記念を勝った。皐月賞は9番人気で3着に入ったが、東京優駿とNHK杯はどちらも12着だった。1976年の天皇賞（春）は17頭立ての12番人気で、逃げてロングホークをクビ差振り切った。続く函館記念は8番人気で7馬身差のレコード勝ちを収め、京都記念（秋）も大逃げで当時の日本レコードを出した。一方で2番人気に推された有馬記念は6着に沈んだ。1978年は京都記念（春）と鳴尾記念を勝ち、7頭立ての宝塚記念では2着に4馬身差をつけた。1979年の宝塚記念の13着が最後のレースになった。種牡馬としては成績を残せず、産駒には気性の難しい馬が多かったとされる。母の父として京都ハイジャンプの勝ち馬などを出し、2001年に永眠した。' },
 { name:'コクサイプリンス', years:'1974〜1979年', record:'32戦5勝', mainWins:['1975 京都新聞杯','1975 菊花賞','1976 アメリカジョッキークラブカップ（2着）','1976 鳴尾記念（2着）'],
   text:'1974年にデビューし、函館3歳ステークスは11番人気で7着と、同期のテスコガビーにかなわなかった。1975年の春は7連敗が続いたが、5月の300万下を9馬身差で勝って連敗を止め、6月のエーデルワイスステークスも勝った。日本短波賞とセントライト記念はともに3着だった。京都新聞杯は6番人気で、不良馬場のなか1番人気のロングホークをアタマ差退けて重賞を初めて勝った。続く菊花賞は4番人気で、3番手を追走し、直線で先頭に立って粘り切った。同世代にはイシノアラシ、ロングホーク、ハーバーヤングがいた。1976年はアメリカジョッキークラブカップと鳴尾記念で2着に入ったが、1番人気の天皇賞（春）は不良馬場で10着に大敗した。その後は勝てず、1979年1月のオープン戦の11着を最後に引退した。種牡馬にはなれなかった。' },
 { name:'テスコガビー', years:'1974〜1976年', record:'10戦7勝', mainWins:['1974 京成杯3歳ステークス','1975 京成杯','1975 阪神4歳牝馬特別','1975 桜花賞','1975 優駿牝馬'],
   text:'「女カチドキ」と呼ばれた牝馬。1974年9月にデビューし、京成杯3歳ステークスを2着に6馬身差のレコードで勝って、最優秀3歳牝馬に選ばれた。1975年の京成杯では牡馬を相手に勝ったが、東京4歳ステークスはカブラヤオーにクビ差の2着で、初めて敗れた。阪神4歳牝馬特別をレコードで逃げ切り、桜花賞は1分34秒9で2着に1.9秒の差をつけた。当時の桜花賞で最も大きな着差とされる。その後のトライアルでは疲れが残って3着に敗れたが、1番人気のオークスは2着に8馬身差をつけて二冠を果たした。この年の最優秀4歳牝馬に選ばれた。1976年5月にダート1200メートルのオープンで復帰したが6着に終わった。1977年1月に調教中の心臓麻痺でこの世を去り、仔は残せなかった。' },
 { name:'テイタニヤ', years:'1975〜1977年', record:'25戦7勝', mainWins:['1976 クイーンカップ','1976 桜花賞','1976 優駿牝馬','1976 有馬記念（5着）'],
   text:'1975年8月のデビュー戦は出遅れて2着だった。ゲートの練習を重ねて臨んだ次の新馬戦では先手を奪い、8馬身差のレコードタイで勝った。いちょう特別などを勝ち、最優秀3歳牝馬に選ばれた。1976年はクイーンカップで重賞を初めて勝った。2番人気の桜花賞は出遅れて後方から追い上げ、直線で大外に出して1馬身半差で勝った。1番人気のオークスは好位から直線で先頭に立ち、ニッショウダイヤをクビ差退けて二冠を果たした。秋のエリザベス女王杯は1番人気だったが、同じ厩舎のディアマンテが勝って4着に終わり、牝馬三冠はならなかった。続く有馬記念は13番人気で5着に入り、この年の最優秀4歳牝馬に選ばれた。1977年11月のカブトヤマ記念の6着が最後のレースになった。繁殖では8頭がデビューしたが目立った成績は残せず、1998年に放牧中の心臓麻痺で生涯を閉じた。' },
 { name:'ホクトボーイ', years:'1975〜1979年', record:'41戦13勝', mainWins:['1976 阪神大賞典','1977 朝日チャレンジカップ','1977 京都記念（秋）','1977 天皇賞（秋）','1979 スワンステークス'],
   text:'テスコボーイの産駒で、同じ年に生まれたトウショウボーイ、テンポイント、グリーングラスに次ぐ存在とされた。1975年10月に京都でデビューし、1976年はムーンライトハンデキャップをレコードで勝ち、阪神大賞典で重賞を初めて勝った。菊花賞は17着だった。1977年の天皇賞（春）は10番人気で3着に入り、秋に朝日チャレンジカップと京都記念（秋）を勝った。天皇賞（秋）は5番人気で、後方から追い込んでトウショウボーイとグリーングラスを抜き去り、クラウンピラードに2馬身半差をつけた。同じ父の産駒のなかでも長い距離に向き、展開や重いハンデに左右される面があった。1978年の宝塚記念はエリモジョージの逃げに屈して3着、2番人気の有馬記念は14着だった。1979年にスワンステークスを勝ち、有馬記念の5着で引退した。種牡馬としては障害の重賞勝ち馬ダイテンスパルタや地方の重賞馬を出し、1987年に天国へ旅立った。' },
 { name:'クライムカイザー', years:'1975〜1977年', record:'21戦5勝', mainWins:['1975 ライラック賞','1976 京成杯','1976 弥生賞','1976 東京優駿'],
   text:'トウショウボーイ、テンポイント、グリーングラスと同じ世代に属する。1975年6月にデビューし、ライラック賞をレコードで勝った。1976年の京成杯を1馬身1/4差で勝って重賞を初めて勝ち、東京4歳ステークスはテンポイントに半馬身及ばず2着だった。弥生賞はボールドシンボリに2馬身差をつけたが、3番人気の皐月賞は5着に終わった。4番人気の東京優駿は、直線で先に抜け出したトウショウボーイを交わして1馬身半差で勝った。このときの強引にも見える騎乗から「犯罪皇帝」とも呼ばれた。秋は神戸新聞杯と京都新聞杯でトウショウボーイの2着に敗れ、単枠指定を受けた菊花賞はグリーングラスの5着だった。1977年の宝塚記念の6着が最後のレースで、一度も1番人気にならず、掲示板を外したのもこの一戦だけだった。種牡馬としては共同通信杯4歳ステークスのマイネルブレーブを出し、2000年に心臓麻痺で息を引き取った。' },
 { name:'インターグロリア', years:'1977〜1979年', record:'21戦9勝', mainWins:['1977 桜花賞','1977 エリザベス女王杯','1978 読売杯マイラーズカップ','1978 有馬記念（2着）'],
   text:'1977年のデビュー戦を1400メートルのレコードで大差勝ちし、負けないまま桜花賞を勝った。その後は体調を崩し、4歳牝馬特別で9着、オークスで14着に敗れた。この年は阪神牝馬特別も勝った。エリザベス女王杯は3番人気で、内ラチ沿いの後方で脚をため、直線でリニアクインを半馬身差し切った。最優秀4歳牝馬に選ばれている。1978年はマイラーズカップを勝ち、京都牝馬特別を不良馬場で5馬身差で勝った。暮れの有馬記念では直線でカネミノブに交わされ、1馬身差の2着だった。この年は最優秀5歳以上牝馬に選ばれた。1979年は主戦騎手がけがをして別の騎手が乗り、京都牝馬特別を勝ったあと、有馬記念の9着で引退した。繁殖ではテスコボーイやマルゼンスキーと配合されたが仔は振るわず、12年続けて仔を産んだのち、1995年にこの世を去った。' },
 { name:'カネミノブ', years:'1976〜1981年', record:'37戦8勝', mainWins:['1978 アルゼンチン共和国杯','1978 日本経済賞','1978 有馬記念','1980 目黒記念（春）','1980 毎日王冠'],
   text:'1976年9月に東京でデビューし、2戦目の新馬戦をレコードで勝った。1977年のクラシックは皐月賞6着、東京優駿3着、菊花賞5着と勝てなかった。1978年はアルゼンチン共和国杯で重賞を初めて勝ち、日本経済賞も3馬身差で続けて勝った。秋は毎日王冠と目黒記念（秋）で2着、天皇賞（秋）で5着だった。有馬記念は9番人気だったが、直線で先頭に立ち、外から迫った同期のインターグロリアを退けてレコードで勝った。この年の年度代表馬に選ばれた。1979年は6戦して勝てず、有馬記念は審議の末3着だった。1980年は目黒記念（春）と毎日王冠を勝ち、有馬記念は2番人気で再び3着だった。1981年のアメリカジョッキークラブカップの4着で引退した。種牡馬としては毎日杯のキーミノブなど重賞勝ち馬を出したが、1993年を最後に消息がわかっていない。' },
 { name:'テンメイ', years:'1976〜1982年', record:'62戦13勝', mainWins:['1977 菊花賞（2着）','1978 天皇賞（秋）','1979 京都大賞典'],
   text:'母は天皇賞（秋）を勝ったトウメイ。1976年にデビューし、1977年の菊花賞は9番人気で、1番人気のラッキールーラを退けて先頭に立ったが、ゴール前でプレストウコウに差されて2着だった。1978年の阪神大賞典は1番人気で6着に敗れた。同じ年の天皇賞（秋）はゲートの不具合で発走がやり直された。プレストウコウが大逃げを打つなか、大外12番枠から出たテンメイが直線で捉え、半馬身差で重賞を初めて勝った。母と子の天皇賞制覇は史上初めてだった。1979年は中京で行われた京都大賞典をレコードで勝ったが、これが中央での最後の勝ち星になった。1980年の宝塚記念の12着を最後に岩手の水沢へ移り、7勝を挙げたが重賞は勝てなかった。1982年のシアンモア記念の4着で引退した。種牡馬としては目立った産駒を出せず、1993年に骨折がもとで母より先に天国へ旅立った。' },
 { name:'ハードバージ', years:'1976〜1977年', record:'11戦3勝', mainWins:['1977 毎日杯','1977 皐月賞','1977 東京優駿（2着）'],
   text:'2歳の1976年は4戦して勝てず、1977年1月の京都の未勝利戦で初めて勝った。クロッカス賞は5着だったが、重賞に初めて挑んだ毎日杯を10番人気で1馬身半差で勝った。皐月賞は8番人気で、最後の直線で内ラチ沿いを突いて先行馬を交わし、2着のラッキールーラに2馬身半差をつけた。東京優駿は1番人気に推された。序盤に2度前が塞がって後方からの追走となり、直線で大外から追い込んで先頭に立ったが、ラッキールーラにクビ差届かず2着だった。レース後の疲れは激しく、そのあと屈腱炎を発症して、これが最後のレースになった。1980年に引退し、1981年から種牡馬となったが産駒は振るわず、1986年にシンジケートが解散した。乗用馬にも向かず、観光会社に引き取られて引き馬や馬術ショーに使われた。1987年7月に放牧中の日射病で息を引き取った。' },
 { name:'ラッキールーラ', years:'1976〜1980年', record:'24戦6勝', mainWins:['1977 弥生賞','1977 皐月賞（2着）','1977 東京優駿','1980 札幌日経賞'],
   text:'1976年8月に函館でデビューした。1977年の弥生賞は5番人気で、初めて拍車を着けて逃げ、レコードで勝った。皐月賞は先頭で直線に入ったが、内を突いたハードバージに交わされ2馬身半差の2着だった。1番人気のNHK杯も4着に敗れた。東京優駿は9番人気で、先頭争いから抜け出し、追い込んだハードバージを退けて勝った。秋は京都新聞杯でプレストウコウの2着に敗れ、1番人気の菊花賞は速い流れの2番手から失速して15着に終わった。12月に左前脚を傷めて2年休み、1980年6月の札幌日経賞を逃げ切って32か月ぶりに勝った。その年の函館記念を最後に引退した。種牡馬としてはきさらぎ賞のトチノルーラーを出した。1990年に韓国へ渡り、そこで残した仔から韓国の最優秀内国産馬が出たが、1991年に事故の骨折がもとでこの世を去った。' },
 { name:'インターグシケン', years:'1977〜1979年', record:'23戦9勝', mainWins:['1978 きさらぎ賞','1978 NHK杯','1978 菊花賞','1979 スポーツニッポン賞金杯'],
   text:'テスコボーイの産駒で、1977年6月にデビューし、2戦目の札幌の新馬戦で初勝利を挙げた。紅葉杯をレコードで勝ったが、デイリー杯3歳ステークスと阪神3歳ステークスはどちらも2着だった。1978年はきさらぎ賞で重賞を初めて勝ち、皐月賞はファンタストにクビ差の2着だった。NHK杯も勝ったが、東京優駿は6着で初めて掲示板を外した。菊花賞は3番人気で、チェリーリュウの大逃げで流れが速くなるなか中団で脚をためた。直線で先頭に立ったサクラショウリを交わし、追い込んだキャプテンナムラを半馬身抑えて、当時のレコードで勝った。1979年の金杯（西）を61キロを背負って差し切ったあと脚を傷めて長く休み、復帰して2戦目の有馬記念の13着で引退した。種牡馬としてはイブキファイブワンやショウリテンユウなどを出したが、1988年に心臓の病で急逝した。' },
 { name:'サクラショウリ', years:'1977〜1980年', record:'24戦8勝', mainWins:['1978 東京4歳ステークス','1978 東京優駿','1978 セントライト記念','1979 アメリカジョッキークラブカップ','1979 宝塚記念'],
   text:'1977年6月にデビューし、ダートの3戦は勝てず、4戦目の芝で初勝利を挙げた。朝日杯3歳ステークスは3着だった。1978年は東京4歳ステークスで重賞を初めて勝ったが、弥生賞と皐月賞ではそのとき破ったファンタストに敗れ、皐月賞は出遅れて3着だった。2番人気の東京優駿は6、7番手を進み、直線半ばで先頭に立って、外から迫ったアグネスホープを半馬身抑えた。秋はセントライト記念を勝ったが、単枠指定で1番人気の菊花賞はインターグシケンの5着だった。この年の最優秀4歳牡馬に選ばれている。1979年はアメリカジョッキークラブカップでグリーングラスに競り勝ち、目黒記念（春）も勝った。天皇賞（春）はカシュウチカラの2着だったが、宝塚記念をレコードで勝った。1980年の目黒記念（春）を最後に引退した。種牡馬としては皐月賞と菊花賞を勝ったサクラスターオーを出し、1999年に老衰で永眠した。' },
 { name:'シービークロス', years:'1977〜1982年', record:'26戦7勝', mainWins:['1979 日刊スポーツ賞金杯','1979 毎日王冠','1979 目黒記念（秋）'],
   text:'芦毛の馬体で後方から追い込み、「白い稲妻」と呼ばれた。1977年11月にデビューし、1978年の皐月賞は最後方から進んで5着、東京優駿は7着だった。1979年は金杯（東）で重賞を初めて勝ち、天皇賞（春）は直線で進路を失って3着に敗れた。秋の毎日王冠を東京2000メートルのコースレコードで勝ち、1番人気の目黒記念（秋）も2500メートルの日本レコードで勝った。天皇賞（秋）は右前脚の繋靱帯炎で回避し、このけがを何度も繰り返して長い休みが続いた。1980年の天皇賞（春）は1番人気で4着、天皇賞（秋）は最下位だった。1982年4月のオープンで復帰して勝ったが、次の日経賞を取り消してそのまま引退した。種牡馬としては天皇賞を春秋とも勝ったタマモクロスを出した。1991年、馬房で息絶えているのが見つかり、全身に広がった黒色腫が原因とされる。' },
 { name:'プリテイキャスト', years:'1977〜1980年', record:'41戦8勝', mainWins:['1980 ダイヤモンドステークス','1980 天皇賞（秋）'],
   text:'気性が激しく、逃げなければ力を出せないのにスタートが悪く、先頭に立つと暴走気味になることもあった。母は米国で活躍した名牝タイプキャスト。1977年11月の新馬戦は出遅れて6着で、1978年に未勝利戦を勝ち上がり、函館の特別戦やクリスマスハンデキャップを勝った。1980年のダイヤモンドステークスで重賞を初めて勝ったが、天皇賞（春）は15着に沈んだ。同じ年の天皇賞（秋）は重馬場の11頭立てで8番人気だった。スタートを決めて単独で大きく逃げ、後ろの馬たちが牽制し合うなかを逃げ切り、2着のメジロファントムに7馬身差をつけた。カツラノハイセイコやホウヨウボーイもこのレースに出ていた。暮れの有馬記念は大差の最下位に終わり、これが最後のレースになった。この年の最優秀5歳以上牝馬に選ばれている。繁殖では仔出しが悪く、1995年に喉頭がんのため安楽死の措置がとられた。' },
 { name:'ハツシバオー', years:'1977〜1979年', record:'17戦11勝', mainWins:['1978 羽田盃','1978 東京ダービー','1978 東京王冠賞','1978 東京大賞典'],
   text:'タケシバオーの産駒で、大井で走った。1977年7月にデビューし、この年は7戦5勝だった。1978年は年明けの初戦と京浜盃を勝ち、羽田盃では黒潮盃の勝ち馬タイガームサシに2馬身差をつけた。東京ダービーは逃げ切り、同じタイガームサシに6馬身差をつけた。秋の東京盃は3着に敗れて連勝が7で止まったが、東京記念でトドロキヒリュウを破った。8頭立ての東京王冠賞を5馬身差で逃げ切り、史上3頭目の南関東三冠馬となった。1番人気の東京大賞典も2馬身半差で勝ち、四冠を取った。1979年は金盃で落馬して競走を中止し、帝王賞はハツマモルの2着だった。そのあと中央に移って天皇賞（秋）を目指したが、脚を傷めて出られず、推薦で出た有馬記念の13着が最後のレースになった。種牡馬としては朝日チャレンジカップのハツシバエースを出したが、1995年に用途が変わって以降の消息はわかっていない。' },
 { name:'アグネスレディー', years:'1978〜1980年', record:'18戦5勝', mainWins:['1979 優駿牝馬','1979 エリザベス女王杯（2着）','1980 京都記念（春）','1980 朝日チャレンジカップ'],
   text:'1978年10月のデビュー戦は追い込んで届かず2着で、2戦目の新馬戦で初めて勝ち、白菊賞も勝った。1979年の桜花賞は2番人気で、苦手の重馬場に6着と敗れた。オークスは1番人気で、5、6番手から直線で抜け出し、ナカミサファイアに2馬身半差をつけて勝った。秋のエリザベス女王杯も1番人気で、不良馬場の直線で先頭に立ったが、ゴール手前でミスカブラヤに交わされ2着だった。1980年の京都記念はメジロトランザムとの競り合いをハナ差で制した。宝塚記念は不良馬場で最下位に沈んだが、秋の朝日チャレンジカップでファインドラゴンやシルクスキーとの競り合いに勝ち、これを最後に引退した。繁殖では1990年の桜花賞馬アグネスフローラを産んだ。その仔のアグネスフライトが東京優駿を、アグネスタキオンが皐月賞を勝っている。1993年に馬運車のなかで暴れて背骨を折り、この世を去った。' },
 { name:'ビンゴガルー', years:'1978〜1979年', record:'16戦7勝', mainWins:['1978 朝日杯3歳ステークス','1979 皐月賞','1979 京王杯オータムハンデキャップ','1979 セントライト記念'],
   text:'1978年8月に札幌でデビューし、新馬戦を2馬身半差で勝ったが、直線で外ラチに寄るなど気性に不安を見せた。ダートで2戦勝てなかったあと芝で連勝し、朝日杯3歳ステークスは6番人気で後方から差し切り、サクラアケボノに1馬身1/4差をつけた。この年の最優秀3歳牡馬に選ばれている。1979年は年明けからリキアイオーに3度続けて敗れたが、3番人気の皐月賞は直線でリキアイオーを捉え、カツラノハイセイコに3/4馬身差をつけて勝った。東京優駿は馬群で位置を取れずに4着だった。秋は京王杯オータムハンデキャップをトップハンデで古馬相手に勝ち、セントライト記念も勝った。単枠指定で1番人気の菊花賞は早めに動いて失速し、ハシハーミットの3着だった。有馬記念では種子骨を折って競走を中止し、引退した。ハート形の流星を持ち、勝負服とそろいのメンコを着けて走った。種牡馬としては道営の重賞馬ホロトマイケルなどを出し、1987年に小腸捻転で天国へ旅立った。' },
 { name:'カツラノハイセイコ', years:'1978〜1981年', record:'23戦8勝', mainWins:['1979 東京優駿','1980 目黒記念（秋）','1981 マイラーズカップ','1981 天皇賞（春）'],
   text:'ハイセイコーの初年度産駒にあたる。1978年9月にデビューした。1979年の皐月賞は体調が整わず、後方から追い込んだがビンゴガルーに3/4馬身及ばず2着だった。1番人気の東京優駿はリンドプルバンをハナ差抑え、ダービーレコードを0.1秒縮めて勝った。父がタケホープに敗れたレースだった。この年の最優秀4歳牡馬に選ばれている。1980年は目黒記念（秋）を勝ったが、1番人気の天皇賞（秋）はプリテイキャストの逃げ切りを許して6着だった。暮れの有馬記念は直線で先頭に立ったが、斜行したところをホウヨウボーイにハナ差差されて2着に終わった。1981年はマイラーズカップを勝ち、天皇賞（春）はカツアールをクビ差抑えて、父が勝てなかったもう一つの大レースを取った。ファン投票1位の宝塚記念はそのカツアールの2着で、これが最後のレースになった。種牡馬としてはオークス2着のユウミロクや地方の重賞馬を出し、2009年に33歳で生涯を閉じた。' },
 { name:'ニチドウタロー', years:'1978〜1980年', record:'11戦5勝', mainWins:['1978 中京3歳ステークス','1980 天皇賞（春）'],
   text:'1978年10月にデビューし、中京3歳ステークスを1番人気で勝った。左前脚の骨瘤のため休養が長く、1979年の神戸新聞杯は5着、京都新聞杯は8着、菊花賞は6着と勝てなかった。1980年4月に阪神のオープンを勝った。天皇賞（春）は連闘での出走で、3番人気だった。道中は引っ掛かる面を見せたが、最後の直線で抜け出し、メジロトランザムに1馬身半差をつけて勝った。勝ちタイムの3分18秒7は芝3200メートルの日本レコードとされる。続く宝塚記念は不良馬場で外を回り、10着に敗れた。その後に骨瘤が再発し、調教を強めると脚を痛めるため、復帰をあきらめて引退した。1981年から種牡馬となり、1990年のシンザン記念を勝ったニチドウサンダーを出した。母の父としては日経新春杯とアルゼンチン共和国杯を勝ったゴーゴーゼットを出し、1999年に永眠した。' },
 { name:'カツアール', years:'1978〜1983年', record:'45戦11勝', mainWins:['1979 黒潮盃','1980 ダイオライト記念','1980 帝王賞','1980 大井記念','1981 宝塚記念'],
   text:'大井でデビューし、1978年は3戦2勝だった。1979年は黒潮盃を勝ったが、1番人気に推された羽田盃と東京ダービーは4着と3着に終わり、どちらもソウルシヤトーが勝った。8月の戸塚記念で重賞2勝目を挙げた。1980年はダイオライト記念、帝王賞、大井記念、中央競馬招待競走を含めて5連勝した。1981年に中央へ移り、天皇賞（春）はカツラノハイセイコの2着だった。続く宝塚記念ではそのカツラノハイセイコを差し切って勝った。地方出身の宝塚記念馬は、ヒカルタカイ、ハイセイコーに続いて3頭目だった。中央で挙げた勝ち星はこの1つだけで、その後は1983年まで17戦して勝てずに引退した。地方では24戦10勝を挙げている。種牡馬としては目立った産駒を残せず、1991年に種牡馬を引退した。' },
 { name:'アンバーシャダイ', years:'1980〜1983年', record:'34戦11勝', mainWins:['1981 目黒記念（秋）','1981 有馬記念','1982 アメリカジョッキークラブカップ','1983 アメリカジョッキークラブカップ','1983 天皇賞（春）'],
   text:'父はノーザンテースト。1980年にデビューし、東京優駿は19番人気で9着だった。1981年は毎日王冠でジュウジアローの2着、天皇賞（秋）はホウヨウボーイの4着に終わった。目黒記念（秋）を勝って臨んだ有馬記念は3番人気で、モンテプリンスの横を抜け、ホウヨウボーイに2馬身半ほどの差をつけて大レースを初めて勝った。1982年はアメリカジョッキークラブカップを勝ったが、天皇賞（春）はモンテプリンスの2着、有馬記念は直線で先頭に立ちながらゴール寸前でヒカリデュールに交わされて2着だった。1983年はアメリカジョッキークラブカップを連覇した。4度目の挑戦の天皇賞（春）は1番人気で、出遅れながら直線でホリスキーとの競り合いを半馬身制した。獲得賞金は初めて4億円を超えた。秋は天皇賞3着、ジャパンカップ6着で、引退レースの有馬記念は3着だった。種牡馬としては宝塚記念のメジロライアンなど15頭の重賞勝ち馬を出し、孫にメジロドーベルがいる。2007年に放牧中に骨折し、安楽死の措置がとられた。' },
 { name:'キョウエイプロミス', years:'1979〜1983年', record:'29戦7勝', mainWins:['1982 ダイヤモンドステークス','1982 毎日王冠','1983 天皇賞（秋）','1983 ジャパンカップ（2着）'],
   text:'1979年12月に中山で初めて勝った。1980年のスプリングステークスは13着、函館記念は5着で、そのあと脚の不安で1年休んだ。1981年8月に函館で復帰し、ステイヤーズステークスで2着に入った。1982年はダイヤモンドステークスで重賞を初めて勝ち、宝塚記念ではモンテプリンスの4着だった。秋は毎日王冠を勝ったが、天皇賞（秋）は7着、1番人気の目黒記念は12着に敗れた。暮れの有馬記念はヒカリデュール、アンバーシャダイに次ぐ3着だった。1983年の天皇賞（秋）は、人気を分け合ったタカラテンリュウを直線で交わし、1馬身半差で勝った。続くジャパンカップではスタネーラとの競り合いにアタマ差で敗れたが、日本馬として初めて2着に入った。このレースの途中で右前脚の繋靱帯を傷め、競走能力を失って引退した。この年の最優秀5歳以上牡馬に選ばれている。種牡馬としては目立った産駒を残せず、2003年にこの世を去った。' },
 { name:'ハギノトップレディ', years:'1979〜1981年', record:'11戦7勝', mainWins:['1980 桜花賞','1980 京都牝馬特別','1980 エリザベス女王杯','1981 高松宮杯'],
   text:'1979年8月の函館の新馬戦を2秒以上の差で勝ち、芝1000メートルの日本レコード57秒2を出した。1980年は桜花賞の指定オープンで3着に入って出走権を取り、桜花賞は2番人気で逃げ切った。オークスは不良馬場で17着に大敗した。秋の復帰戦では1600メートルをレコードで9馬身差で逃げ切り、京都牝馬特別も勝った。エリザベス女王杯は3番人気で、ゆっくりしたペースで逃げてタケノハッピーを抑えた。この年の最優秀4歳牝馬に選ばれている。1981年の宝塚記念は直線で捕まって4着だったが、高松宮杯は6馬身差で逃げ切り、母イットーとの母娘制覇を果たした。続く巴賞では桜花賞馬ブロケードとの一騎打ちを、59キロを背負ってアタマ差で制した。毎日王冠の8着を最後に引退した。繁殖ではトウショウボーイとの間に、安田記念とスプリンターズステークスを勝ったダイイチルビーを産んだ。2003年に天国へ旅立った。' },
 { name:'ハワイアンイメージ', years:'1979〜1984年', record:'39戦11勝', mainWins:['1980 皐月賞','1980 ラジオたんぱ賞','1980 福島記念','1983 アメジストステークス'],
   text:'いちばん重いときで570キロ台の大きな体で、ダートや重い馬場を得意とし「重戦車」と呼ばれた。1979年12月にデビューした。1980年の皐月賞は雨で不良馬場となり、4番人気だった。1番人気のトウショウゴッドが競走を中止するなか、ゴール前でオペックホースとの競り合いをクビ差で制した。勝ち時計の2分10秒2は、1954年以降で2番目に遅い記録とされる。東京優駿は6番人気と評価が低く、14着に敗れた。夏から秋は福島でラジオたんぱ賞、福島民友カップ、不良馬場の福島記念を勝ち、この年の獲得賞金は当時の最多だった。その後は有馬記念で7着と12着に終わるなど大きいレースでは振るわず、1983年にアメジストステークスを勝った。1984年2月のフェブラリーハンデキャップの7着で引退した。種牡馬としてはオープン特別を2勝したハワイアンコーラルを出した。1990年に放牧中に骨折し、安楽死の措置がとられた。' },
 { name:'ヒカリデュール', years:'1980〜1983年', record:'45戦10勝', mainWins:['1981 東海桜花賞','1982 朝日チャレンジカップ','1982 有馬記念','1983 サンケイ大阪杯'],
   text:'大井でデビューし、4歳の1980年は南関東の三冠レースで4着、4着、2着だった。その後は東海の公営競馬に移り、1981年の東海桜花賞を勝った。1982年秋に中央へ移り、初戦の朝日チャレンジカップは11頭立ての7番人気で、重馬場を最後方から差し切った。天皇賞（秋）はメジロティターンの2着、ジャパンカップは日本馬で最先着の5着だった。有馬記念は3番人気で、スタート直後に不利を受けて後方2番手からの競馬になった。直線に入ってもほぼ最後方にいたが、一気に追い込み、アンバーシャダイをアタマ差かわして勝った。この年の年度代表馬に選ばれている。1983年はサンケイ大阪杯を勝ったが、3番人気の天皇賞（春）は2周目の向正面の手前で脚を折って競走を中止し、引退した。種牡馬としては産駒に恵まれず、1992年に用途が変わって以降の消息はわかっていない。' },
 { name:'モンテプリンス', years:'1979〜1982年', record:'24戦7勝', mainWins:['1980 NHK杯','1980 セントライト記念','1982 東京新聞杯','1982 天皇賞（春）','1982 宝塚記念'],
   text:'道悪を苦手としたことから「太陽の王子」と呼ばれた。1979年にデビューし、1980年のNHK杯を2着に7馬身差で圧勝して重賞を初めて勝った。大本命の東京優駿は直線でオペックホースにクビ差交わされて2着だった。秋はセントライト記念を勝ったが、菊花賞も先に抜け出しながらゴール直前でノースガストにクビ差差され、クラシックは勝てなかった。1981年の天皇賞（秋）は5番人気で先行し、ホウヨウボーイとの長い叩き合いを写真判定のハナ差で落とした。ジャパンカップは日本馬で最上位の2番人気だったが7着だった。惜敗が続いて「無冠の帝王」とも呼ばれた。1982年は東京新聞杯を勝ち、1番人気の天皇賞（春）を中団からの追い込みでレコード勝ちした。続く宝塚記念もカツアールに1馬身半差をつけて勝ったが、ファン投票1位の有馬記念は脚を傷めた影響もあって11着に終わり、引退した。種牡馬としては札幌記念のグレートモンテなどを出し、2002年に永眠した。' },
 { name:'オペックホース', years:'1979〜1984年', record:'41戦4勝', mainWins:['1980 皐月賞（2着）','1980 東京優駿','1981 有馬記念（4着）'],
   text:'1979年10月に中京の新馬戦でデビューして3着となり、11月に阪神のオープンを勝った。1980年の皐月賞は不良馬場でハワイアンイメージとの競り合いにクビ差敗れて2着だった。東京優駿では1番人気のモンテプリンスをゴール前でクビ差交わして勝ち、この年の最優秀4歳牡馬に選ばれた。ところがそこから勝てなくなり、菊花賞は10着だった。1981年の有馬記念で4着に入ったほかは、天皇賞（春）は3度出て12着、7着、8着、宝塚記念も2度出て6着と9着に終わった。ダービーのあとの連敗は32まで伸び、それまでの記録を大きく上回った。「史上最弱のダービー馬」とも呼ばれた。1984年には障害への転向が計画されたが、批判を受けて取りやめになった。同じ年12月のウインターステークスの12着が最後のレースになった。種牡馬としては道営の二冠馬ベストンダンデイを出し、2005年に老衰で生涯を閉じた。' },
 { name:'カツトップエース', years:'1980〜1981年', record:'11戦4勝', mainWins:['1980 りんどう賞','1981 皐月賞','1981 東京優駿'],
   text:'1980年7月のデビュー戦はビッグディザイヤーに6馬身離された2着で、次の札幌のダートの新馬戦で勝った。10月のりんどう賞も勝ったが、ソエに悩まされて調整が思うように進まず、朝日杯3歳ステークスは10着に終わった。1981年の皐月賞は16番人気だった。1枠1番から先頭を奪い、前半1000メートルを62秒1の遅いペースに落として、ロングミラーをクビ差振り切った。単勝6920円は皐月賞で2番目に高い配当だった。直後のNHK杯はサンエイソロンの2着だった。3番人気の東京優駿は2番手の集団につけ、最後のコーナーで内から抜け出した。並びかけたサンエイソロンとの写真判定を、20センチのハナ差で制して二冠を果たした。この年の最優秀4歳牡馬に選ばれたが、これが最後のレースになり、1982年8月に引退した。種牡馬としては種付けが減り、1990年に韓国へ贈られ、1991年に股関節炎が悪化してこの世を去った。' },
 { name:'テンモン', years:'1980〜1981年', record:'9戦5勝', mainWins:['1980 白菊賞','1980 朝日杯3歳ステークス','1981 京成杯','1981 優駿牝馬'],
   text:'1980年7月に新潟の新馬戦をハナ差で勝ってデビューした。重い馬場が苦手で、新潟3歳ステークスは3着、カンナ賞は4着に敗れた。白菊賞では、のちにクラシックで活躍するサンエイソロンを2馬身差で破った。朝日杯3歳ステークスは1分35秒5で勝ち、牝馬として史上7頭目の勝ち馬になった。この年の最優秀3歳牝馬に選ばれている。1981年の京成杯も1番人気で牡馬をクビ差抑えたが、クイーンカップは熱を出した影響もあって3着だった。不良馬場の桜花賞は3番人気で、ブロケードに3馬身半差の2着に終わった。1番人気のオークスは前半1000メートル59秒1の速い流れを中団で進み、直線で抜け出して2馬身半ほどの差をつけた。レースでは素直で御しやすい馬だった。休養中の8月に牧場が台風に襲われ、腰から左後脚に重いけがを負って引退した。繁殖では後遺症で出産の負担が大きく、目立った仔は少なかった。2001年に老衰で息を引き取った。' },
 { name:'ハッピープログレス', years:'1980〜1984年', record:'27戦11勝', mainWins:['1982 CBC賞','1984 スプリンターズステークス','1984 京王杯スプリングカップ','1984 安田記念','1984 CBC賞'],
   text:'直線の追い込みを持ち味とした短距離馬。1980年11月にデビューし、1982年のCBC賞で重賞を初めて勝ち、1983年には阪急杯も勝った。1984年のスプリンターズステークスは1番人気で、後方3番手から直線で大外に出して1馬身3/4差で勝った。続く京王杯スプリングカップも1番人気で、後方5番手から追い上げてドウカンヤシマを3/4馬身抑えた。安田記念は予定の騎手が落馬で負傷して乗り替わりとなり、2番人気だった。出走22頭のうち16頭が重賞勝ち馬という顔ぶれのなか、後方から大外に出して1馬身3/4差で勝ち、3連勝で「春の短距離三冠」を果たした。秋はスワンステークスで3着、マイルチャンピオンシップで2着と、どちらもニホンピロウイナーに敗れた。引退レースのCBC賞は61キロを背負い、シャダイソフィアを半馬身抑えて勝った。種牡馬としては九州で供用され、2000年に阪神競馬場での展示のあとに急性心不全で天国へ旅立った。' },
 { name:'ミナガワマンナ', years:'1981〜1984年', record:'25戦7勝', mainWins:['1981 菊花賞','1982 アルゼンチン共和国杯','1983 アルゼンチン共和国杯','1984 ジューンステークス'],
   text:'シンザンの産駒で、2戦目で初勝利を挙げ、水仙賞も続けて勝った。1981年の皐月賞は5番人気で12着、4歳中距離ステークスを勝って臨んだ東京優駿は先行したが4コーナーで脚が止まり8着だった。ラジオたんぱ賞で2着に入ってオープンに上がった。秋は3戦して5着、10着、9着と振るわず、菊花賞は14番人気だった。そこで1番人気のサンエイソロンを4馬身突き放して勝ち、シンザン産駒として初めてのクラシックの勝ち馬になった。サンエイソロンには前のレースで1.4秒の差をつけられていた。有馬記念は9着だったが、1982年のアルゼンチン共和国杯を勝ち、翌年は追い込んできた馬たちをハナ差抑えて連覇した。1984年の引退レースのジューンステークスも勝った。父と同じ牧場で種牡馬となってアサヒジュピターなどを出し、2007年に老衰で永眠した。' },
 { name:'メジロティターン', years:'1981〜1983年', record:'27戦7勝', mainWins:['1981 セントライト記念','1982 日経賞','1982 天皇賞（秋）'],
   text:'芦毛の馬で、1981年1月の新馬戦は3着に終わり、4戦目で初めて勝った。夏は函館の800万下を大差で、HTB賞を5馬身差で勝ち、セントライト記念を1馬身半差で勝って重賞を初めて勝った。そのあと左後脚の骨折がわかり、菊花賞はあきらめた。1982年の日経賞は1番人気で2着に10馬身差をつけた。宝塚記念は9着だった。天皇賞（秋）は4番人気で、直線で先頭に立ってそのまま押し切り、ヒカリデュールに1馬身半差をつけた。勝ちタイムの3分17秒9は日本レコードだった。父メジロアサマに続く天皇賞馬で、この年に新しくできた最優秀父内国産馬に選ばれた。1983年は8戦して勝てず、有馬記念の6着で引退した。種牡馬としては天皇賞（春）を2度勝ったメジロマックイーンを出し、父子三代の天皇賞制覇になった。2009年に31歳で老衰のため生涯を閉じた。' },
 { name:'モンテファスト', years:'1980〜1984年', record:'27戦8勝', mainWins:['1983 目黒記念（秋）','1984 天皇賞（春）'],
   text:'モンテプリンスの全弟にあたる。1980年11月の新馬戦は4着で、1981年1月の4戦目で初めて勝った。慢性的な脚の不安があって何度も長く休み、勝ちきれないレースが続いて、兄と比べて「愚弟」とからかわれた。1983年の目黒記念（秋）で重賞を初めて勝ち、天皇賞（秋）は4着だった。1984年の天皇賞（春）は6番人気で、地方出身のミサキネバアーや、圧倒的1番人気の菊花賞馬ホリスキーを破って勝った。2年前に兄が勝ったレースで、兄弟での天皇賞制覇となった。このときの馬体重550キロは、八大競走の勝ち馬で最も重い記録とされる。同じ年の天皇賞（秋）の14着が最後のレースになった。種牡馬としては、スピードが重んじられるようになった時代に長距離の血統は評価されなかった。羽田盃と東京ダービーで2着のキングフォンテンが目立つ程度で、2010年に心不全でこの世を去った。' },
 { name:'ハギノカムイオー', years:'1982〜1983年', record:'14戦8勝', mainWins:['1982 スプリングステークス','1982 神戸新聞杯','1982 京都新聞杯','1983 宝塚記念','1983 高松宮杯'],
   text:'1979年10月のセリで、それまでの最高額5000万円を大きく上回る1億8500万円で落札され、「華麗なる一族の御曹司」と呼ばれた。1982年1月にデビューし、スプリングステークスでサルノキングを相手に先手を取って逃げ切り、重賞を初めて勝った。1番人気の皐月賞はゲイルスポートに先頭を譲って前半600メートル34秒9の速い流れに巻き込まれ、16着に大敗した。NHK杯も12着に終わり、東京優駿には出なかった。秋は神戸新聞杯でダービー馬バンブーアトラスを退け、京都新聞杯は初めて2番手に控えて勝った。1番人気の菊花賞は1000メートル59秒5で大逃げして失速し、ホリスキーが勝った。1983年はスワンステークスを勝ち、宝塚記念を単騎で逃げて5馬身差、2分12秒1の日本レコードで勝った。高松宮杯も勝ったが、ジャパンカップと有馬記念はどちらも逃げつぶれて最下位だった。種牡馬としては目立った産駒を出せず、2013年に34歳で天国へ旅立った。' },
 { name:'ビクトリアクラウン', years:'1981〜1984年', record:'14戦6勝', mainWins:['1981 新潟3歳ステークス','1982 クイーンカップ','1982 クイーンステークス','1982 エリザベス女王杯'],
   text:'1981年7月の新潟のデビュー戦は、パドックで蹄鉄の打ち替えを嫌がって暴れ、返し馬なしで走って6着だった。その年に新しくできた新潟3歳ステークスで最初の勝ち馬となり、3歳牝馬ステークスも勝って最優秀3歳牝馬に選ばれた。1982年のクイーンカップは1番人気で、ファイブソロンに一度並ばれながら差し返した。ところが桜花賞の12日ほど前に調教で左前脚の骨を折り、桜花賞とオークスに出られず、「幻のクラシック馬」と呼ばれた。7か月半ぶりの復帰戦となったクイーンステークスを1番人気で勝ち、東京牝馬特別は古馬のスイートネイティブの2着だった。エリザベス女王杯は2番人気で、先行したメジロカーラを捉えて勝った。この年の最優秀4歳牝馬に選ばれている。唯一の牝馬として出た有馬記念は5着だった。1983年は下位が続き、1984年1月のアメリカジョッキークラブカップの7着で引退した。繁殖では重賞勝ち馬を出せず、2007年に老衰で息を引き取った。' },
 { name:'ホリスキー', years:'1982〜1984年', record:'19戦5勝', mainWins:['1982 菊花賞','1983 天皇賞（春）（2着）','1984 エイプリルステークス'],
   text:'父はマルゼンスキー。1982年1月のデビュー戦は11着に大敗したが、2戦目の未勝利戦を9馬身差で勝ち、4月に条件戦を2つ勝った。東京優駿は5番人気で、勝ったバンブーアトラスに大きく離されて9着だった。菊花賞は9番人気で、1番人気のハギノカムイオーが大逃げを打つ速い流れから抜け出して勝った。勝ちタイムの3分5秒4はレコードで、1992年にライスシャワーが破るまで保たれた。父の産駒として初めての八大競走の勝利だった。その後は慢性的な脚の不安に悩まされた。1983年の天皇賞（春）はアンバーシャダイとの競り合いに半馬身敗れて2着、1984年は3着と、長い距離で力を見せた。1984年4月のエイプリルステークスを勝ち、6番人気の天皇賞（秋）の15着で引退した。種牡馬としては中山記念のユキノサンライズやセントライト記念の勝ち馬を出し、2003年に老衰で永眠した。' },
 { name:'カツラギエース', years:'1982〜1984年', record:'22戦10勝', mainWins:['1983 NHK杯','1983 京都新聞杯','1984 宝塚記念','1984 毎日王冠','1984 ジャパンカップ'],
   text:'1982年9月にデビューした。1983年のNHK杯を9番人気で大外枠から勝って重賞を初めて勝ったが、皐月賞は11着、東京優駿は6着だった。秋の京都新聞杯は2着に6馬身差をつけ、ミスターシービーは4着だった。2番人気の菊花賞は距離が合わず20着に終わった。1984年はサンケイ大阪杯と京阪杯を勝ち、1番人気の宝塚記念でスズカコバンを退けた。毎日王冠ではミスターシービーをアタマ差抑えたが、天皇賞（秋）は折り合いを欠いて5着だった。ジャパンカップは10番人気で、先行して逃げ切り、ベッドタイムとシンボリルドルフを抑えた。日本で調教された馬がこのレースを勝ったのは初めてだった。引退レースの有馬記念はシンボリルドルフの2着だった。種牡馬としてはダート向きの産駒が多く、東京ダービーのアポロピンクや中央の重賞を勝ったヤマニンマリーンを出し、2000年に心臓発作でこの世を去った。' },
 { name:'ギャロップダイナ', years:'1982〜1986年', record:'42戦10勝', mainWins:['1985 天皇賞（秋）','1986 東京新聞杯','1986 安田記念','1986 有馬記念（2着）'],
   text:'ノーザンテーストの産駒で、1982年に新潟でデビューした。1985年の札幌日経賞ではスタート直後に騎手が落ち、乗り手のいないまま先頭でゴールしたが、記録は競走中止だった。同じ年の天皇賞（秋）は13番人気で、1番人気のシンボリルドルフを半馬身差で破った。勝ちタイムの1分58秒7はレコードで、単勝8820円は当時の天皇賞で最も高い配当だった。このときの実況から「あっと驚くギャロップダイナ」という言い回しが生まれた。1986年は東京新聞杯を59キロで勝ち、1番人気の安田記念をホリノカチドキに1馬身3/4差をつけて勝った。夏はフランスに遠征し、ジャック・ル・マロワ賞で12着、ムーラン・ド・ロンシャン賞で10着だった。秋は天皇賞4着、ジャパンカップ10着のあと、引退レースの有馬記念で11番人気ながらダイナガリバーに半馬身差の2着に入った。種牡馬としてはエプソムカップのマルマツエースなどを出し、2006年に天国へ旅立った。' },
 { name:'シャダイソフィア', years:'1982〜1985年', record:'24戦6勝', mainWins:['1982 函館3歳ステークス','1983 桜花賞','1983 サファイヤステークス','1985 阪急杯'],
   text:'1982年8月に函館でデビューし、新馬戦を2着に10馬身差のレコードで勝った。続く函館3歳ステークスも単勝1.2倍に応えた。1983年の桜花賞は不良馬場で行われ、ミホクイーンらをクビ差抑えて八大競走を制した。同じ牧場の生まれで1番人気のダイナカールは3着だった。そのあとオークスではなく東京優駿に挑み、14番人気で17着に大敗して陣営は批判を浴びた。秋はサファイヤステークスを勝ち、距離を不安視されたエリザベス女王杯でロンググレイスの2着に粘った。1984年はマイルチャンピオンシップでニホンピロウイナーの4着に入った。1985年は約1年4か月ぶりに勝ち、続く阪急杯をトップハンデで2馬身半差で勝った。秋のスワンステークスは1番人気だったが、直線の手前で他馬に挟まれて転倒し、脱臼のため安楽死の措置がとられた。' },
 { name:'ロンググレイス', years:'1983〜1985年', record:'16戦6勝', mainWins:['1983 ローズステークス','1983 エリザベス女王杯','1984 スポーツニッポン賞金杯'],
   text:'1983年1月の新馬戦でデビューし、夏に条件戦を勝ち上がった上がり馬だった。秋は重賞初挑戦のローズステークスを3番人気で勝った。続くエリザベス女王杯は1番人気に応え、桜花賞馬シャダイソフィアを2着に退けた。1984年は金杯（西）を勝って古馬の重賞でも結果を出した。春のサンケイ大阪杯はカツラギエースの2着、秋の京都大賞典は1番人気でスズカコバンの2着だった。天皇賞（秋）は7番人気で3着に入り、牡馬の一線級と互角に走った。この着順は、1997年にエアグルーヴが勝つまで、グレード制以後の天皇賞（秋）での牝馬の最高着順だった。1985年1月の金杯（西）で5着に敗れたのが最後のレースになった。生まれた牧場で繁殖に入ったが、産駒は6頭にとどまり、血を伝える牝馬は続かなかった。2002年に22歳で生涯を閉じた。' },
 { name:'ダイナカール', years:'1982〜1985年', record:'18戦5勝', mainWins:['1982 3歳牝馬ステークス','1983 優駿牝馬','1983 ターコイズステークス'],
   text:'1982年10月にデビューし、新馬戦から白菊賞、3歳牝馬ステークスと3連勝して最優秀3歳牝馬に選ばれた。1983年はクイーンカップで5着に敗れて初めて土がつき、報知杯4歳牝馬特別も2着だった。桜花賞は1番人気に推されたが、同じ牧場の生まれのシャダイソフィアに敗れて3着だった。優駿牝馬は2番人気で、5頭が横一線になる大接戦を長い写真判定の末にハナ差で制した。2着から5着までの差もハナ、アタマ、ハナ、アタマというわずかなものだった。古馬になってからはアメリカジョッキークラブカップ2着などがあったが、重賞は勝てず1985年の中山記念で引退した。繁殖に入って9頭を産み、4番仔のエアグルーヴが優駿牝馬と天皇賞（秋）を勝って年度代表馬になった。孫にアドマイヤグルーヴやルーラーシップ、曾孫に東京優駿を勝ったドゥラメンテがいる。1999年に種付けの事故でこの世を去った。' },
 { name:'サンオーイ', years:'1982〜1986年', record:'29戦13勝', mainWins:['1983 羽田盃','1983 東京ダービー','1983 東京王冠賞','1983 東京大賞典','1984 札幌日経賞'],
   text:'大井でデビューした。1983年に京浜盃で重賞を初めて勝ち、羽田盃を4馬身差、東京ダービーを7馬身差で勝った。秋の東京王冠賞も1番人気に応え、南関東の三冠馬になった。三冠の2着はいずれもセレブレイシヨンだった。暮れの東京大賞典では古馬を破り、四冠馬と呼ばれることもある。同じ年に中央ではミスターシービーが三冠を果たしている。1984年に中央へ移り、札幌日経賞を勝った。安田記念ではハッピープログレスの3着、毎日王冠ではカツラギエースの逃げを捕まえられずミスターシービーとの初対決も3着だった。天皇賞（秋）は6着に終わった。1986年は上山で走り、最後の樹氷賞は1番人気で競走を中止した。種牡馬になってダービーグランプリを勝ったトミシノポルンガを出したが、1989年に心臓麻痺で急逝した。' },
 { name:'テツノカチドキ', years:'1982〜1987年', record:'58戦17勝', mainWins:['1984 東京大賞典','1985 大井記念','1986 大井記念','1987 帝王賞','1987 東京大賞典'],
   text:'大井の馬で、ダートを得意とした。同じ父の産駒には芝で走った馬が多く、その中では異色だった。1984年の東京大賞典は伏兵扱いだったが、向こう正面で先頭に立って押し切った。1985年は大井記念と関東盃を勝ち、福島の地方競馬招待競走も4コーナー先頭から楽勝した。一方で東京記念は60.5キロを背負い、ロッキータイガーとの叩き合いにわずかの差で敗れた。暮れの東京大賞典もスズユウとロッキータイガーに続く3着だった。1986年に大井記念を連覇した。1987年の帝王賞はウメノスペンサーをハナ差抑えて勝った。引退レースの東京大賞典では1周目のスタンド前から逃げる策が当たり、ミハマシヤークに4馬身差をつけた。この勝利で獲得賞金は地方所属馬として初めて3億円を超えた。種牡馬になったが産駒は振るわず、2001年に用途変更された。' },
 { name:'リードホーユー', years:'1982〜1983年', record:'8戦3勝', mainWins:['1982 3歳新馬','1983 京都新聞杯（2着）','1983 有馬記念'],
   text:'1982年7月に阪神の新馬戦を大差で勝ち、クラシックの候補と目された。その後は勝ちきれず、1983年のきさらぎ賞では同じ厩舎のニホンピロウイナーに完敗して4着だった。2月に条件戦を勝った直後に骨折し、春のクラシックには出られなかった。秋に戻ると京都新聞杯でカツラギエースの2着に入り、菊花賞に進んだ。菊花賞は先行して粘ったが4着で、ミスターシービーの三冠を止められなかった。暮れの有馬記念は先行し、4コーナーで先頭に立って押し切った。2着はテュデナムキングで、重賞の初勝利が有馬記念になった。このあと競走能力を失うほどの故障が見つかり、わずか8戦で引退した。種牡馬になったが産駒は少なく、乗馬用の種牡馬に移って1997年に引退した。2009年に29歳で永眠した。' },
 { name:'メジロモンスニー', years:'1982〜1986年', record:'21戦6勝', mainWins:['1983 シンザン記念','1983 皐月賞（2着）','1983 東京優駿（2着）','1985 高松宮杯'],
   text:'1982年6月にデビューし、萩特別などを勝った。後方から追い込む脚質で、1983年のシンザン記念で重賞を初めて勝った。この世代ではミスターシービーのライバルと見られた。皐月賞は後方から追い込んだが、ミスターシービーに半馬身届かず2着だった。東京優駿は2番人気で、ビンゴカンタはかわしたものの、ミスターシービーに1馬身3/4差の2着に敗れた。秋は神戸新聞杯で3着に入ったあと指骨の骨折が分かり、菊花賞には出られなかった。1985年の天皇賞（春）はシンボリルドルフから3秒離された9着だった。それでもこの年に大阪城ステークスと高松宮杯を勝ち、久しぶりに重賞を手にした。1986年の高松宮杯14着が最後のレースになった。種牡馬としては地方の重賞勝ち馬を出すにとどまり、1995年に用途変更された。' },
 { name:'スズパレード', years:'1983〜1988年', record:'25戦12勝', mainWins:['1984 ラジオたんぱ賞','1985 ダービー卿チャレンジトロフィー','1987 中山記念','1987 宝塚記念','1988 サンケイ賞オールカマー'],
   text:'1983年11月に東京の新馬戦を勝ち、クラシックの有力候補になった。1984年は共同通信杯から東京優駿まで4戦続けて4着で、うち3戦はシンボリルドルフが勝った。ダービーのあとラジオたんぱ賞で重賞を初めて勝ち、秋は福島記念も勝った。古馬になって金杯（東）とダービー卿チャレンジトロフィーを勝ったが、脚部不安で何度も長く休んだ。1987年は中山記念を勝ち、宝塚記念ではニッポーテイオーやニシノライデンを退けてG1を制した。同じ世代の牡馬で、シンボリルドルフのほかにG1を勝ったのはこの馬だけだった。1年以上休んだあとの1988年のオールカマーをコースレコードで勝ち、7歳の有馬記念を最後に引退した。古馬になってからの東京では、出たレースすべてで6着以下に終わった。父ソルティンゴは産駒が1世代しかおらず、その数少ない仔の一頭だった。種牡馬としては地方から中央へ移ったスズハグラーを出した。2008年に老衰で天国へ旅立った。' },
 { name:'ロッキータイガー', years:'1983〜1986年', record:'25戦10勝', mainWins:['1984 東京王冠賞','1985 ダイオライト記念','1985 帝王賞','1985 東京記念','1985 ジャパンカップ（2着）'],
   text:'船橋の馬で、1983年9月にデビューした。1984年の雲取賞で新しい主戦騎手を迎え、直線一気の差し切りで勝つと成績が大きく伸びた。羽田盃は3着、東京ダービーは2着で、どちらもキングハイセイコーに敗れた。秋の東京王冠賞では三冠を狙ったキングハイセイコーに大差をつけて勝った。1985年は金盃、ダイオライト記念、帝王賞と勝ち進んだ。東京記念ではジャパンカップの出走権をかけてテツノカチドキと叩き合い、競り勝った。ジャパンカップは15頭中11番人気だったが、後方から追い込んでシンボリルドルフの2着に入った。地方所属馬のジャパンカップでの最高着順で、のちに2004年のコスモバルクが並んだ。暮れの東京大賞典はスズユウの2着だった。1986年8月の関東盃が最後のレースになった。種牡馬としては目立つ産駒が少なく、1996年に引退し、2007年に老衰で息を引き取った。' },
 { name:'トウカイローマン', years:'1983〜1987年', record:'30戦5勝', mainWins:['1984 優駿牝馬','1986 ジューンステークス','1987 京都大賞典'],
   text:'1983年11月に中京でデビューした。1984年の桜花賞は18番人気で4着に入り、勝ったダイアナソロンからは7馬身離されていた。優駿牝馬は9番人気だった。季節外れの低温で芝の状態が悪く、1000メートルを59秒3で通過するハイペースになった。後方から上がってきたダイアナソロンと先頭を争い、1馬身3/4差で勝った。鞍上はデビュー3年目の若い騎手で、これがクラシックの初勝利だった。秋のエリザベス女王杯は4着だった。その後は勝てない時期が長く、1986年のジューンステークスを1番人気で勝った。1987年の京都大賞典は6番人気で、ペルシアンパーソを半馬身退けてオークス以来の重賞を勝った。引退レースの有馬記念に出たことで、JRAの全10場に出走した2頭目の牝馬になった。生まれた牧場で繁殖に入って11頭を産み、2007年にこの世を去った。' },
 { name:'ダイアナソロン', years:'1983〜1985年', record:'13戦5勝', mainWins:['1984 桜花賞','1984 優駿牝馬（2着）','1984 サファイヤステークス'],
   text:'曾祖母は1951年の桜花賞2着馬クモワカで、テンポイントと同じ一族に属する。1983年9月に阪神でデビューし、新馬戦を勝った。1984年はエルフィンステークスを重馬場で勝ったが、阪神4歳牝馬特別は窮屈な競馬で6着だった。桜花賞は中団から直線で内を抜け出し、2着に5馬身差をつけた。グレード制が始まった年で、日本で最初のG1馬になった。優駿牝馬は1番人気だったが、トウカイローマンに交わされて2着だった。秋はサファイヤステークスを勝ったものの、ローズステークスは3着、エリザベス女王杯もキョウワサンダーとキクノペガサスに先着されて3着だった。ジャパンカップでは14着に大敗した。この年の最優秀4歳牝馬に選ばれている。1985年3月のコーラルステークスで競走生活を終えた。繁殖に入り、代表産駒にクエストフォベストがいる。1994年に13歳で生涯を閉じた。' },
 { name:'キョウワサンダー', years:'1983〜1985年', record:'23戦4勝', mainWins:['1984 サファイヤステークス（2着）','1984 エリザベス女王杯','1985 大原ステークス'],
   text:'1983年10月にデビューしたが、初めて勝ったのは13戦目の1984年4月だった。秋に重賞初挑戦のサファイヤステークスで2着に入り、賞金を積んだ。ローズステークスは8着に終わった。エリザベス女王杯は14番人気の伏兵だったが、最後方から直線で一気に追い込んだ。粘るキクノペガサスをアタマ差で捕らえ、桜花賞馬ダイアナソロンは3着だった。暮れの有馬記念ではシンボリルドルフから2.7秒離された10着に終わった。1985年は朝日チャレンジカップ8着、京都大賞典7着と重賞では振るわず、11月の大原ステークスを勝って引退した。サラ系の馬で、グレード制のもとで中央のG1級を勝った唯一のサラ系とされる。繁殖に入ったが、牡馬を1頭産んだだけで急逝した。その仔も未勝利に終わり、血は絶えた。' },
 { name:'ビゼンニシキ', years:'1983〜1984年', record:'10戦6勝', mainWins:['1984 共同通信杯4歳ステークス','1984 弥生賞（2着）','1984 スプリングステークス','1984 皐月賞（2着）','1984 NHK杯'],
   text:'1983年11月に東京の新馬戦を追い込んで大差で勝った。1984年の共同通信杯4歳ステークスで重賞を初めて勝ち、楽勝と評された。弥生賞は1番人気だったが、シンボリルドルフに敗れて2着だった。スプリングステークスはサクラトウコウを相手に逃げ切った。皐月賞は勝ったシンボリルドルフに寄られる不利があり、2着に終わった。東京優駿の前哨戦のNHK杯は楽勝した。ダービーまでシンボリルドルフのほかには負けておらず、そのライバルと呼ばれた。東京優駿は14着に大敗し、距離が課題とされた。秋のスワンステークスで故障して引退した。種牡馬になると、2世代目からダイタクヘリオスやハシノケンシロウなどの重賞勝ち馬を出した。1999年に種付けのとき転倒して頭を打ち、この世を去った。' },
 { name:'ニシノライデン', years:'1984〜1987年', record:'26戦7勝', mainWins:['1984 京都新聞杯','1985 鳴尾記念','1985 阪神大賞典','1987 サンケイ大阪杯'],
   text:'1984年にデビューした。皐月賞6着、東京優駿5着のあと、秋の京都新聞杯で重賞を初めて勝った。菊花賞は2番人気で、直線で先頭に立ったがシンボリルドルフの3着だった。1985年は鳴尾記念と阪神大賞典を勝った。一方で朝日チャレンジカップでは1着で入線しながら、斜行で失格になった。有馬記念は3着だった。1987年はサンケイ大阪杯を勝った。天皇賞（春）は2番人気で、直線で外に斜行してアサヒエンペラーの進路をふさいだ。ミホシンザンとほぼ並んでゴールし、一度は2着と出たが、審議で失格になった。G1で2着以内に入った馬が失格になったのはJRAで初めてだった。この一件から降着制度の導入につながる議論が起き、「降着制度の産みの親」と呼ばれる。宝塚記念は1番人気でスズパレードの3着に終わり、これが最後のレースになった。種牡馬としては活躍馬が出ず、2011年に30歳で天国へ旅立った。' },
 { name:'クシロキング', years:'1984〜1987年', record:'25戦7勝', mainWins:['1986 日刊スポーツ賞金杯','1986 中山記念','1986 天皇賞（春）'],
   text:'1984年9月にデビューした。1985年の皐月賞は13着に終わった。1986年の金杯（東）は1番人気で、5番手から差し切って重賞を初めて勝った。初めての2500メートルだった目黒記念は、レコードで勝ったビンゴチムールに1馬身1/4差まで迫る3着だった。中山記念は1番人気でトウショウペガサスをクビ差退けた。マイラーと見られていたが、重馬場の天皇賞（春）に3番人気で出た。後方から追い上げ、4コーナーで失速したスダホークと先頭のメジロトーマスを交わし、3/4馬身差で勝った。2着は11番人気のメジロトーマスで、連勝複式は当時の天皇賞（春）で最高の配当になった。その後は宝塚記念を1番人気で7着に敗れるなど勝てず、1987年の有馬記念で引退した。種牡馬としては中央で勝ち馬を出せず、乗馬になったのち1996年に事故で生涯を閉じた。' },
 { name:'サクラユタカオー', years:'1984〜1986年', record:'12戦6勝', mainWins:['1985 共同通信杯4歳ステークス','1986 サンケイ大阪杯','1986 毎日王冠','1986 天皇賞（秋）'],
   text:'1984年12月に中山の新馬戦をコースレコードで勝ち、続く万両賞も逃げ切った。1985年の共同通信杯4歳ステークスは不良馬場をクビ差で勝ったが、そのあと骨折が分かり春のクラシックを見送った。8か月半ぶりの京都新聞杯は4着、菊花賞は折り合いを欠いてミホシンザンの4着だった。1986年はサンケイ大阪杯でスダホークをアタマ差退けた。重馬場の天皇賞（春）は14着に大敗した。秋の毎日王冠を1分46秒0の日本レコードで勝つと、天皇賞（秋）も大外16番から日本レコードで勝ち、前哨戦の勝ち馬は本番で勝てないという言い伝えを破った。ジャパンカップは1番人気で6着、有馬記念も6着に終わり引退した。種牡馬としてサクラバクシンオー、エアジハード、ウメノファイバーなどのG1馬を出し、母の父としても活躍馬を残した。2010年に28歳で永眠した。' },
 { name:'シリウスシンボリ', years:'1984〜1988年', record:'26戦4勝', mainWins:['1984 府中3歳ステークス','1985 若葉賞','1985 東京優駿','1988 毎日王冠（2着）'],
   text:'1984年9月の新馬戦を出遅れながら勝った。次の芙蓉特別は1位で入線したが、斜行で失格になった。府中3歳ステークスをクビ差で勝ち、1985年は若葉賞を勝った。東京優駿は皐月賞馬ミホシンザンが骨折で出られず、1番人気に応えてスダホークに3馬身差をつけた。そのあと約2年をヨーロッパで過ごし、フランスを中心に英国、ドイツ、イタリアで14戦したが勝てなかった。キングジョージ6世＆クイーンエリザベスステークスは8着、ロワイヤルオーク賞は3着、ダンシングブレーヴが勝った1986年の凱旋門賞は14着だった。帰国後の1988年の毎日王冠ではオグリキャップの2着に入ったが、ゲートの前でレジェンドテイオーを蹴り、相手を発走除外にさせた。天皇賞（秋）7着のあと骨折が分かり引退した。種牡馬としては北斗盃を勝ったベストファーザーを出し、2012年に30歳でこの世を去った。' },
 { name:'タカラスチール', years:'1984〜1987年', record:'32戦8勝', mainWins:['1985 クイーンカップ','1985 関屋記念','1986 マイルチャンピオンシップ'],
   text:'1984年7月に札幌のダート1000メートルでデビューした。1985年は新春4歳牝馬ステークスに続いてクイーンカップを1番人気で勝ち、重賞を初めて手にした。桜花賞は1番人気だったが、主戦騎手のけがで乗り替わり、ゲートで脚を痛めて15着に沈んだ。夏の関屋記念は古馬を相手に、速い流れを好位から押し切った。同期のエルプスには一度も先着できなかった。1986年の安田記念は7着、スワンステークスは4着だった。マイルチャンピオンシップは6番人気で、それまでの先行策をやめて後方に控えた。外から伸びて直線で抜け出し、ニッポーテイオーとロングハヤブサの追撃を退けた。この勝利でこの年の最優秀5歳以上牝馬に選ばれた。1987年の京王杯スプリングカップを最後に引退し、生まれた牧場で繁殖に入った。産駒は少なく、卵巣の腫瘍のため天国へ旅立った。血は孫の代で絶えた。' },
 { name:'ノアノハコブネ', years:'1985年', record:'10戦3勝', mainWins:['1985 4歳新馬','1985 4歳400万下','1985 優駿牝馬'],
   text:'1985年1月に京都のダート1700メートルでデビューし、好位から差して勝った。そのあと芝では忘れな草賞など4戦して勝てなかった。オークスに出るための賞金を積むため、京都のダートの条件戦を使って勝ち上がった。優駿牝馬は28頭立ての21番人気だった。先行した馬たちが速い流れを作り、いつもどおり最後方を進んだ。直線で失速した馬を外からまとめて交わし、ナカミアンゼリカに1馬身1/4差をつけて勝った。単勝6270円はオークスの最高配当で、まだ破られていない。秋はローズステークス11着、エリザベス女王杯12着と振るわなかった。暮れの阪神大賞典では1周目のスタンド前で寛骨を折って競走を中止し、安楽死の措置がとられた。デビューから1年足らずの競走生活で、子孫は残らなかった。' },
 { name:'エルプス', years:'1984〜1985年', record:'11戦6勝', mainWins:['1984 函館3歳ステークス','1984 テレビ東京賞3歳牝馬ステークス','1985 報知杯4歳牝馬特別','1985 桜花賞','1985 京王杯オータムハンデキャップ'],
   text:'逃げ馬で、2年の競走生活で重賞を5勝した。1984年に函館3歳ステークスとテレビ東京賞3歳牝馬ステークスを勝った。1985年の報知杯4歳牝馬特別は逃げ切ったが、4コーナーで柵の色に驚いて斜行し、他の馬の走りを妨げた。桜花賞は雨で重くなった馬場をハイペースで逃げ、追い込むロイヤルコスマーを半馬身退けた。優駿牝馬は2番人気だったが、体調が整わず外枠で逃げられなかったうえ、距離も合わずに15着だった。秋は京王杯オータムハンデキャップを1分33秒0で勝ち、当時の日本レコードに0.1秒まで迫った。ローズステークスはタケノハナミにゴール前で差され、逃げて初めて負けた。エリザベス女王杯も11着に終わった。この年の最優秀4歳牝馬に選ばれた。繁殖では8頭を産み、2番仔リヴァーガールの仔テイエムオーシャンが桜花賞と秋華賞を勝った。' },
 { name:'リワードウイング', years:'1984〜1987年', record:'20戦4勝', mainWins:['1985 忘れな草賞（2着）','1985 長月特別','1985 エリザベス女王杯'],
   text:'1984年10月に京都の新馬戦でデビューして2着だった。初勝利は5戦目、1985年2月のダートの未勝利戦だった。チューリップ賞は5着、忘れな草賞は2着でクラシックには届かなかったが、条件戦を勝ち上がっていった。ローズステークスは後方に控える策が先行有利の流れに合わず8着だった。続く長月特別を勝ち、エリザベス女王杯に進んだ。20頭立ての6番人気で、後方から直線で大外を一気に差し切った。桜花賞馬エルプス、オークス馬ノアノハコブネ、1番人気アサクサスケールを破り、勝ちタイム2分26秒8は当時のレースレコードだった。その後は宝塚記念9着など1勝もできず、1987年のサンケイ大阪杯を最後に引退した。繁殖では目立つ産駒を出せなかった。晩年は功労馬として過ごし、2008年に老衰で息を引き取った。' },
 { name:'パーシャンボーイ', years:'1985〜1986年', record:'11戦5勝', mainWins:['1986 千葉日報杯','1986 谷川岳ステークス（2着）','1986 宝塚記念'],
   text:'外国産馬で、1985年2月の新馬戦は5着だった。その後2戦続けて2着に入ったが、右後脚をひどく骨折して約10か月休んだ。1986年3月に小倉で復帰すると、400万下と北方特別を続けて勝った。4月の千葉日報杯、5月の1400万下と勝ち進み、春の4か月で遠征を含めて8戦した。谷川岳ステークスでダイナシュガーの2着に敗れて安田記念をあきらめ、宝塚記念に向かった。宝塚記念は3番人気で、前年の天皇賞（春）を勝ったクシロキングを見ながら好位を進み、早めに動いた。直線はメジロトーマスとの一騎打ちになり、1馬身3/4差で勝った。重賞の初勝利がG1で、グレード制が始まってから外国産馬として初めてのG1勝ちだった。このあと屈腱炎を発症して引退した。種牡馬としてはパーシャンスポットなどを出したが、1994年に種付け中の心臓麻痺でこの世を去った。' },
 { name:'スダホーク', years:'1984〜1988年', record:'30戦6勝', mainWins:['1985 弥生賞','1985 東京優駿（2着）','1985 菊花賞（2着）','1986 アメリカジョッキークラブカップ','1986 京都記念','1987 阪神大賞典'],
   text:'1984年11月に東京でデビューした。1985年の弥生賞は5番人気で、4馬身差をつけて重賞を初めて勝った。皐月賞は6着だった。東京優駿は2番人気で、シリウスシンボリに3馬身離されたが、スクラムダイナをハナ差抑えて2着を確保した。菊花賞も2番人気でミホシンザンに1馬身1/4差の2着だった。1986年はアメリカジョッキークラブカップを1馬身差で勝ち、京都記念でメジロヘンリーを3/4馬身退けた。サンケイ大阪杯は1番人気でサクラユタカオーにアタマ差届かず、天皇賞（春）も1番人気で7着に敗れた。1987年の阪神大賞典はマルブツファーストをアタマ差で抑えた。1988年の宝塚記念で8番人気ながら3着に入ったのが最後のレースで、持病の裂蹄が悪くなり引退した。種牡馬のあと乗馬になり、2003年に永眠した。' },
 { name:'ダイナアクトレス', years:'1985〜1988年', record:'19戦7勝', mainWins:['1985 函館3歳ステークス','1987 京王杯オータムハンデキャップ','1987 毎日王冠','1987 ジャパンカップ（3着）','1988 スプリンターズステークス','1988 京王杯スプリングカップ'],
   text:'1985年8月にデビューし、函館3歳ステークスまで3連勝した。1986年はすみれ賞で枠入りを嫌って最下位に敗れ、出走停止と調教再審査の処分を受けて桜花賞に出られなかった。フローラステークスはメジロラモーヌの2着、優駿牝馬は3着だった。1987年の京王杯オータムハンデキャップは芝1600メートルの当時の世界タイレコードで勝った。続く毎日王冠では牡馬を抑えて重賞を連勝した。ジャパンカップは9番人気だったが、後方から追い込んで日本馬で最先着の3着に入った。1988年は東京の1400メートルで行われたスプリンターズステークスを勝ち、京王杯スプリングカップではニッポーテイオーを下した。安田記念は2着だった。毎日王冠では発走前にシリウスシンボリに蹴られて5着に終わり、天皇賞（秋）4着を最後に引退した。繁殖では重賞2勝のステージチャンプとプライムステージを産み、孫からジャパンカップのスクリーンヒーローが出た。' },
 { name:'ダイナガリバー', years:'1985〜1987年', record:'13戦5勝', mainWins:['1986 共同通信杯4歳ステークス','1986 東京優駿','1986 菊花賞（2着）','1986 有馬記念'],
   text:'1985年8月に函館の新馬戦を勝ち、暮れにひいらぎ賞も勝った。1986年の共同通信杯4歳ステークスは1番人気で先行して抜け出し、レースレコードで勝った。皐月賞は2番人気だったが、調整が整わず10着に大敗した。東京優駿は3番人気で、スローペースを前めで進み、直線で先頭に立って半馬身差で勝った。鞍上は史上最年長のダービージョッキーになった。秋はセントライト記念、京都新聞杯とも4着に敗れた。菊花賞は5番人気で、メジロデュレンにクビ差まで迫る2着だった。有馬記念は4番人気で、4番手から内を伸びて同じ馬主のギャロップダイナを従えて勝ち、この年の年度代表馬に選ばれた。1987年は骨折で秋の凱旋門賞挑戦の計画が消え、有馬記念14着を最後に引退した。種牡馬として桜花賞馬ファイトガリバーなど重賞勝ち馬を5頭出した。2012年に29歳で生涯を閉じた。' },
 { name:'ダイナコスモス', years:'1985〜1986年', record:'10戦4勝', mainWins:['1985 朝日杯3歳ステークス（2着）','1986 弥生賞（2着）','1986 皐月賞','1986 ラジオたんぱ賞'],
   text:'1985年9月にデビューし、初戦は3着だった。そのあと新馬戦と400万下を続けて勝った。朝日杯3歳ステークスは後方から追い込んだが、ダイシンフブキの2着だった。1986年の京成杯は1番人気でダイナフェアリーの3着に敗れ、弥生賞もダイシンフブキにわずかに届かず2着だった。皐月賞は5番人気で、中団から直線で早めに先頭に立った。追い込むフレッシュボイスをクビ差抑え、1番人気のダイシンフブキは7着に沈んだ。東京優駿は距離が長く5着がやっとだった。夏のラジオたんぱ賞では58キロを背負い、ニッポーテイオーに1馬身半差をつけて勝った。秋はマイルチャンピオンシップを目指したが、脚部不安が出て早めに引退した。種牡馬として安田記念とマイルチャンピオンシップを勝ったトロットサンダーを出した。2006年に23歳で天国へ旅立った。' },
 { name:'フレッシュボイス', years:'1985〜1989年', record:'26戦7勝', mainWins:['1986 シンザン記念','1986 毎日杯','1986 皐月賞（2着）','1987 日経新春杯','1987 安田記念','1988 サンケイ大阪杯'],
   text:'直線一気の追い込みを武器にし、雨や雪の悪い馬場で強さを見せた。1985年10月にデビューし、1986年のシンザン記念でファイブホマレとの叩き合いをクビ差で制した。雪の中の毎日杯は後方から先行馬をまとめて差し切った。皐月賞は4番人気で追い込んだが、ダイナコスモスにクビ差届かず2着だった。菊花賞は6着だった。1987年は日経新春杯を1番人気で勝った。重馬場の安田記念は3番人気で、大外から追い込んでニッポーテイオーを1馬身1/4差で退け、G1を初めて勝った。1988年は7番人気のサンケイ大阪杯を半馬身差で勝ったが、安田記念の連覇はならず5着だった。1989年の宝塚記念は10番人気ながらイナリワンとの一騎打ちに持ち込み、クビ差の2着だった。その年の有馬記念で引退した。種牡馬としては種付けが少なく、2007年に24歳でこの世を去った。' },
 { name:'メジロデュレン', years:'1985〜1988年', record:'21戦6勝', mainWins:['1986 菊花賞','1987 有馬記念','1988 天皇賞（春）（3着）'],
   text:'1985年8月に函館でデビューした。未勝利戦を勝ったあと、なでしこ賞や樽前山特別、嵐山特別と条件戦を勝ち進んだ。1986年の菊花賞は6番人気だった。遅いペースのなか、逃げるレジェンドテイオーを早めに追い、直線の競り合いでダイナガリバーを抑えた。重賞の初勝利がクラシックになった。1987年の有馬記念は10番人気だった。サクラスターオーとメリーナイスが競走を中止する波乱のなか、好位から抜け出してユーワジェームスを退けた。単勝と枠連の配当は当時の有馬記念の最高だった。1988年は天皇賞（春）でタマモクロスの3着に入ったが、ジャパンカップ11着、有馬記念5着と勝てずに引退した。半弟のメジロマックイーンはのちに天皇賞（春）を連覇した。種牡馬としては新潟ジュニアカップのライデンホースを出し、2009年に26歳で永眠した。' },
 { name:'ダイシンフブキ', years:'1985〜1986年', record:'6戦5勝', mainWins:['1985 京成杯3歳ステークス','1985 朝日杯3歳ステークス','1986 弥生賞'],
   text:'1985年9月に中山の新馬戦を1番人気で勝ち、4馬身差をつけた。京成杯3歳ステークスは5頭立てだった。有力馬のメジロラモーヌが出遅れて流れが乱れるなか、好位から抜け出して3馬身半差で重賞を初めて勝った。朝日杯3歳ステークスは圧倒的な支持を受け、内で控えて直線で抜け出し、ダイナコスモスに1馬身半差をつけた。無敗の4連勝で、この年の最優秀3歳牡馬に選ばれた。1986年の弥生賞は初めての2000メートルで、超スローペースのなかダイナコスモスとの競り合いをクビ差で制し、5連勝とした。皐月賞は1番人気だったが、直線で伸びずダイナコスモスに捕らえられて7着だった。レースのあと骨折が分かり、そのまま一度も走らずに引退した。種牡馬としては繁殖牝馬が集まらず、1995年に用途変更された。その後の行方は分かっていない。' },
 { name:'イナリワン', years:'1986〜1990年', record:'25戦12勝', mainWins:['1987 東京王冠賞','1988 東京大賞典','1989 天皇賞（春）','1989 宝塚記念','1989 有馬記念'],
   text:'1986年12月に大井でデビューし、地方では14戦9勝を挙げた。1987年に東京王冠賞で重賞を初めて勝ち、1988年は東京大賞典を勝った。1989年に中央へ移り、天皇賞（春）は4番人気で直線で抜け出して勝った。移籍後の初勝利がG1になり、走破タイムは当時のコースレコードを0.4秒縮めた。宝塚記念も2番人気でフレッシュボイスをクビ差退けた。毎日王冠はオグリキャップとの写真判定でハナ差の2着に敗れた。天皇賞（秋）は6着、ジャパンカップは11着だった。有馬記念は4番人気から追い込み、スーパークリークとの写真判定をハナ差で制した。走破タイムは当時のコースレコードを1.1秒更新し、この年の年度代表馬に選ばれた。オグリキャップ、スーパークリークとともに平成三強と呼ばれる。1990年は天皇賞（春）でスーパークリークに半馬身差の2着に入り、宝塚記念4着で引退した。種牡馬として東京王冠賞を勝ったツキフクオーを出し、2016年に32歳で生涯を閉じた。' },
 { name:'サクラスターオー', years:'1986〜1987年', record:'7戦4勝', mainWins:['1987 弥生賞','1987 皐月賞','1987 菊花賞'],
   text:'母サクラスマイルは生後2か月ほどで腸捻転でこの世を去り、高齢のスターロツチが母代わりになって育った。1986年10月にデビューしたが、2戦目のあと脚を痛めて4か月休んだ。1987年の弥生賞は6番人気で、大外から差し切ってクビ差で勝った。皐月賞は2番人気で、後方から外を回って差し切り、ゴールドシチーに2馬身半差をつけた。そのあと繋靭帯炎で東京優駿を回避し、温泉やプールで脚を癒やした。菊花賞は約半年ぶりのぶっつけで9番人気だったが、内を通って抜け出し、再びゴールドシチーを半馬身退けた。皐月賞から202日の間隔は菊花賞の最長記録だった。有馬記念はファン投票1位で1番人気に推されたが、3コーナーから4コーナーで脚を痛めて競走を中止した。種牡馬として血を残すための治療が続けられたが、1988年5月に安楽死の措置がとられた。この年の年度代表馬に選ばれている。' },
 { name:'マックスビューティ', years:'1986〜1988年', record:'19戦10勝', mainWins:['1987 桜花賞','1987 優駿牝馬','1987 神戸新聞杯','1987 ローズステークス','1987 エリザベス女王杯（2着）'],
   text:'1986年にデビューし、函館3歳ステークスは4着、ラジオたんぱ杯3歳牝馬ステークスは2着だった。1987年はサンスポ賞4歳牝馬特別を勝って桜花賞に進んだ。桜花賞は1番人気で、2着のコーセイに8馬身差をつけた。勝ちタイム1分35秒1はテスコガビーのレースレコードに0.2秒差だった。優駿牝馬は不良馬場と距離が不安視されたが、1番人気に応えてクリロータリーを捕らえ、2馬身差で牝馬二冠を果たした。秋は神戸新聞杯とローズステークスを勝ち、三冠をかけてエリザベス女王杯に臨んだ。1番人気だったが、タレンティドガールに2馬身差をつけられて2着に敗れた。この年の最優秀4歳牝馬に選ばれた。有馬記念は10着に終わり、1988年のスワンステークスを最後に引退した。繁殖では初仔マックスジョリーが桜花賞とオークスでともに3着に入った。2002年に蹄葉炎のため18歳で天国へ旅立った。' },
 { name:'メリーナイス', years:'1986〜1988年', record:'14戦5勝', mainWins:['1986 朝日杯3歳ステークス','1987 東京優駿','1987 セントライト記念'],
   text:'1986年8月にデビューした。朝日杯3歳ステークスは中団の後ろから4コーナーで外へ出し、直線で抜け出してホクトヘリオスに1馬身半差をつけた。この年の最優秀3歳牡馬にゴールドシチーと並んで選ばれた。1987年のスプリングステークスはひどくイレ込んで出遅れ、9着に敗れた。皐月賞も体調が整わず7着だった。東京優駿は4番人気で、好位から4コーナーで進出して抜け出し、2着に6馬身差をつける独走だった。3歳王者はダービーを勝てないという言い伝えを26年ぶりに破った。秋はセントライト記念を1番人気で勝ったが、菊花賞は1番人気で折り合いを欠いて9着だった。有馬記念ではスタート直後につまずいて転倒し、競走を中止した。1988年の函館記念を最後に、調教中の骨折で引退した。種牡馬として共同通信杯4歳ステークスのマイネルリマークを出し、2009年に25歳で息を引き取った。' },
 { name:'タレンティドガール', years:'1987〜1988年', record:'11戦4勝', mainWins:['1987 桃花賞','1987 優駿牝馬（3着）','1987 漁火特別','1987 エリザベス女王杯'],
   text:'1987年1月の新馬戦でデビューし、2月にダートの未勝利戦を勝った。3月の桃花賞も勝ったが、フラワーカップは11着に大敗した。優駿牝馬は11番人気で3着に入り、勝ったのはマックスビューティだった。夏は函館の漁火特別を勝ち、クイーンステークスは1番人気で3着だった。エリザベス女王杯は4番人気だった。直線で先頭に立った二冠馬マックスビューティを外から差し切り、2馬身差をつけた。重賞の初勝利がG1になり、牝馬三冠を阻んだ。半兄のニッポーテイオーが天皇賞（秋）とマイルチャンピオンシップを勝った秋で、兄妹で1か月のうちにG1を3勝した。有馬記念は12着、1988年2月の中山牝馬ステークス5着が最後のレースだった。繁殖では不受胎が多かったが、孫の代からヴィクトリアマイルのホエールキャプチャなどの重賞勝ち馬が出た。2008年に24歳でこの世を去った。' },
 { name:'ゴールドシチー', years:'1986〜1989年', record:'20戦3勝', mainWins:['1986 コスモス賞','1986 阪神3歳ステークス','1987 皐月賞（2着）','1987 菊花賞（2着）'],
   text:'1986年6月にデビューし、3戦目で勝ち上がった。函館のコスモス賞を勝ち、札幌3歳ステークスは後方から追い込んで2着だった。阪神3歳ステークスはサンキンハヤテとの写真判定をアタマ差で制し、この年の最優秀3歳牡馬にメリーナイスと並んで選ばれた。1987年のスプリングステークスではパドックで激しく焦れ込み、6着だった。皐月賞は直前に疝痛を起こして11番人気だったが、2着に入った。東京優駿は2番人気で、向こう正面で気を抜いて下がり4着だった。京都新聞杯では3位で入線しながら、スタート直後の斜行で他の馬を転ばせて失格になった。菊花賞は2番人気で、サクラスターオーに半馬身届かず2着だった。そのあとは勝てず、1989年の宝塚記念10着が最後になった。引退後は乗馬になったが、1990年に放牧中に骨折し、安楽死の措置がとられた。' },
 { name:'オグリキャップ', years:'1987〜1990年', record:'32戦22勝', mainWins:['1988 高松宮杯','1988 有馬記念','1989 マイルチャンピオンシップ','1989 ジャパンカップ（2着）','1990 安田記念','1990 有馬記念'],
   text:'笠松でデビューして12戦10勝を挙げ、1988年1月に中央へ移った。芦毛の怪物と呼ばれる。移籍後はペガサスステークスや毎日杯、ニュージーランドトロフィー4歳ステークスなど重賞を勝ち続け、古馬との高松宮杯と毎日王冠も勝った。天皇賞（秋）はタマモクロスの2着、ジャパンカップは3着だったが、暮れの有馬記念は2番人気で勝ち、芦毛の馬として初めてこのレースを制した。1989年の天皇賞（秋）はスーパークリークの2着だった。マイルチャンピオンシップは1番人気で、バンブーメモリーとの叩き合いをハナ差で制した。ジャパンカップでは当時の世界レコードで走ったが、ホーリックスに敗れて2着だった。1990年の安田記念はコースレコードで勝った。天皇賞（秋）6着、ジャパンカップ11着と大敗が続いたあと、引退レースの有馬記念で勝ち、奇跡の復活と呼ばれた。スーパークリーク、イナリワンと並んで平成三強とされる。種牡馬としては中央の重賞勝ち馬を出せず、2010年に放牧中の骨折により25歳で天国へ旅立った。' },
 { name:'サクラチヨノオー', years:'1987〜1989年', record:'10戦5勝', mainWins:['1987 朝日杯3歳ステークス','1988 弥生賞','1988 東京優駿'],
   text:'マルゼンスキーの仔で、1987年8月にデビューした。朝日杯3歳ステークスは1番人気でツジノショウグンをクビ差退け、重賞の初勝利をG1で挙げた。父に続く親子での制覇だった。最優秀3歳牡馬の記者投票ではサッカーボーイに大差で敗れた。1988年の共同通信杯4歳ステークスは1番人気で4着だった。弥生賞は単枠指定のサッカーボーイらを相手に逃げ切った。皐月賞は2番人気で、ヤエノムテキとディクターランドに差されて3着だった。東京優駿は3番人気だった。直線でメジロアルダンに交わされたが、ゴール前で差し返してクビ差で勝ち、勝ちタイム2分26秒3はレコードだった。昭和最後のダービー馬になった。そのあと長く休み、1989年の安田記念16着で復帰した。宝塚記念で故障して最下位に終わり、引退した。種牡馬として皐月賞2着のサクラスーパーオーや地方重賞を勝ったマイターンを出し、2012年に27歳で永眠した。' },
 { name:'サッカーボーイ', years:'1987〜1988年', record:'11戦6勝', mainWins:['1987 阪神3歳ステークス','1988 中日スポーツ賞4歳ステークス','1988 函館記念','1988 マイルチャンピオンシップ'],
   text:'1987年8月にデビューした。阪神3歳ステークスは1番人気で、2着に8馬身差をつけて勝った。勝ちタイム1分34秒5はコースレコードを0.6秒縮め、テンポイントの再来と報じられた。この年の最優秀3歳牡馬に選ばれた。1988年の弥生賞は1番人気だったがサクラチヨノオーの3着に敗れ、皐月賞は飛節炎で回避した。東京優駿も1番人気だったが、直線で伸びず15着に終わり、距離が敗因とされた。夏の中日スポーツ賞4歳ステークスは皐月賞馬ヤエノムテキを相手に直線で差し切った。続く函館記念は古馬を相手に5馬身差で独走し、コースレコードを出した。天皇賞（秋）は脚の故障で断念した。マイルチャンピオンシップは後方から追い込んで4馬身差で勝ち、最優秀スプリンターに選ばれた。有馬記念はゲートで暴れて歯を折り、出遅れながら最後方から3着まで追い上げた。翌年は故障が続いて引退した。種牡馬としてナリタトップロードやヒシミラクルを出し、2011年に26歳で生涯を閉じた。' },
 { name:'スーパークリーク', years:'1987〜1990年', record:'16戦8勝', mainWins:['1988 菊花賞','1989 京都大賞典','1989 天皇賞（秋）','1990 産経大阪杯','1990 天皇賞（春）','1990 京都大賞典'],
   text:'1987年12月にデビューした。1988年の京都新聞杯は直線で前をふさがれ、鞍上のムチも当たる不利を受けて6着だった。菊花賞は3番人気で、4コーナーから内を突いて抜け出し、ガクエンツービートに5馬身差をつけて勝った。鞍上にとって初めてのG1勝利だった。有馬記念は3位で入線したが、進路妨害で失格になった。1989年は京都大賞典をコースレコードで勝った。天皇賞（秋）は2番人気で、1番人気のオグリキャップをクビ差退けた。ジャパンカップは1番人気で4着、有馬記念は直線で先頭に立ったが、ゴール寸前でイナリワンにハナ差で交わされた。1990年は産経大阪杯を勝ち、天皇賞（春）でイナリワンを半馬身抑えて秋春連覇を果たした。秋の京都大賞典で連覇したのが最後のレースになった。オグリキャップ、イナリワンと並んで平成三強とされる。種牡馬としては特別競走の勝ち馬を出せず、2010年に25歳でこの世を去った。' },
 { name:'バンブーメモリー', years:'1987〜1991年', record:'39戦8勝', mainWins:['1989 安田記念','1989 スワンステークス','1989 マイルチャンピオンシップ（2着）','1990 高松宮杯','1990 スプリンターズステークス'],
   text:'1987年11月に京都でデビューし、初戦は5着だった。1989年の春、道頓堀ステークスで芝の初勝利を挙げた。そこから連闘で安田記念に挑み、10番人気ながら末脚でダイゴウシュールを下した。秋はスワンステークスを勝った。マイルチャンピオンシップはオグリキャップとの叩き合いになり、写真判定でハナ差の2着に敗れた。のちに死闘と呼ばれる一戦となった。1990年は高松宮杯を勝った。この年G1になったスプリンターズステークスはハイペースに乗って抜け出し、1分7秒8の日本レコードでルイテイトを破った。初代電撃王の異名はこの勝利から来ている。マイルチャンピオンシップは単枠指定で臨んだが、パッシングショットに敗れて2年続けて2着だった。1989年と1990年の最優秀スプリンターに選ばれた。1991年は安田記念3着、宝塚記念最下位と勝てず、マイルチャンピオンシップ8着で引退した。種牡馬としては地方の重賞勝ち馬を2頭出し、2014年に29歳で天国へ旅立った。' },
 { name:'ヤエノムテキ', years:'1988〜1990年', record:'23戦8勝', mainWins:['1988 皐月賞','1988 京都新聞杯','1988 鳴尾記念','1989 産経大阪杯','1990 天皇賞（秋）'],
   text:'1988年2月にデビューした。毎日杯は重馬場で4着だったが、抽選を通って皐月賞に出た。この年の皐月賞は東京で行われ、9番人気ながらディクターランドに3/4馬身差で勝った。芝での初勝利が皐月賞だった。東京優駿は4着、中日スポーツ賞4歳ステークスはサッカーボーイに半馬身差の2着だった。秋は京都新聞杯を1番人気で勝ったが、菊花賞は1番人気で10着に沈んだ。鳴尾記念は58キロのトップハンデでハナ差勝った。1989年は産経大阪杯を3馬身半差で圧勝したが、宝塚記念7着、天皇賞（秋）4着と平成三強の壁に当たった。1990年の天皇賞（秋）はメジロアルダンとの競り合いをアタマ差で制し、1分58秒2のコースレコードで2つ目のG1を手にした。この年の最優秀父内国産馬に選ばれた。有馬記念では入場直後に鞍上を落として放馬し、7着で引退した。種牡馬としては地方の重賞勝ち馬を出し、2014年に29歳で息を引き取った。' },
 { name:'アラホウトク', years:'1988年', record:'10戦4勝', mainWins:['1988 報知杯4歳牝馬特別（2着）','1988 桜花賞','1988 サンケイスポーツ賞4歳牝馬特別'],
   text:'1988年1月にデビューし、1年足らずで競走生活を終えた。報知杯4歳牝馬特別は4番人気で、スカーレットリボンの速い逃げに屈して2着だった。桜花賞は5番人気だった。直線で同じ厩舎のシヨノロマンを差し切り、1分34秒8の桜花賞レコードで勝った。ゴール前は同じ厩舎の2頭が並び、1着と2着を占めた。続くサンケイスポーツ賞4歳牝馬特別も大逃げのスルーオベストを差し切り、シヨノロマンに再び先着した。優駿牝馬は1番人気で7着に敗れた。秋は右膝に不安を抱え、神戸新聞杯5着、ローズステークス6着と単枠指定に応えられなかった。引退レースのエリザベス女王杯は2番人気で4着だった。この年の最優秀4歳牝馬に選ばれた。繁殖では9頭を産み、オースミコンドルが東京優駿に出た。1998年に種付けの事故により14歳でこの世を去った。孫のエキマエが兵庫チャンピオンシップを勝っている。' },
 { name:'ダイユウサク', years:'1988〜1992年', record:'38戦11勝', mainWins:['1991 スポーツニッポン賞金杯','1991 産経大阪杯（2着）','1991 有馬記念'],
   text:'1988年10月に京都でデビューした。勝ち上がりには時間がかかり、1989年に新潟で挙げた初勝利は高配当になった。条件戦を一つずつ勝ち進み、1990年の天皇賞（秋）でG1に初めて挑んで7着だった。1番人気のオグリキャップには先着していた。1991年の金杯（西）は1番人気に応えて重賞を初めて勝った。産経大阪杯はホワイトストーンの2着、マイルチャンピオンシップは5着だった。暮れの有馬記念は14番人気だった。直線で伸び、圧倒的な1番人気のメジロマックイーンを差し切った。勝ちタイム2分30秒6は当時の中山2500メートルのコースレコードで、単勝は13790円になった。翌1992年は天皇賞（春）9着、宝塚記念8着と勝てず、スワンステークス15着が最後のレースになった。祖母は第1回ビクトリアカップを勝ったクニノハナ。種牡馬としての産駒は17頭と少なく、2013年に28歳で永眠した。' },
 { name:'ミヤマポピー', years:'1987〜1989年', record:'14戦3勝', mainWins:['1987 3歳新馬','1988 北洋特別','1988 エリザベス女王杯'],
   text:'カブラヤオーの仔で、半兄にG1を3勝したタマモクロスがいる。1987年11月に中京の新馬戦を勝ってデビューした。1988年の夏に函館の北洋特別を勝ち、2勝目を挙げた。秋は格上挑戦でローズステークスに出て4着に入り、エリザベス女王杯の優先出走権を得た。エリザベス女王杯は6番人気だった。単枠指定で1番人気のシヨノロマンとの争いをハナ差で制し、条件馬の身でG1を勝った。古馬になって金杯（西）4着、京都記念は2番人気で3着と健闘した。産経大阪杯は7着、天皇賞（春）は9着に終わり、これが最後のレースになった。繁殖では5番仔ゼンノカルナックが中京2歳ステークスを勝った。6番仔の子孫からアドマイヤビジンが出ている。2014年に繁殖を退き、その後の行方は分かっていない。' },
 { name:'メジロアルダン', years:'1988〜1991年', record:'14戦4勝', mainWins:['1988 東京優駿（2着）','1989 高松宮杯','1990 天皇賞（秋）（2着）'],
   text:'半姉に1986年の牝馬三冠馬メジロラモーヌがいる。1988年3月にデビューし、NHK杯で2着に入って東京優駿の優先出走権を得た。東京優駿は直線で先頭に立ったが、サクラチヨノオーに差し返されて2着だった。レースのあと骨折が分かり、長く休んだ。1989年5月にメイステークスを快勝し、続く高松宮杯をレコードで勝って重賞を初めて手にした。秋は毎日王冠と天皇賞（秋）でともに3着に入ったが、平成三強の壁を越えられなかった。1990年の天皇賞（秋）はヤエノムテキと競り合い、アタマ差の2着に敗れた。屈腱炎で休むことが多く、1991年に引退した。種牡馬としてアメリカジョッキークラブカップ3着のメジロスティードなどを出した。2000年に中国へ渡り、2002年に種付け中の心臓発作で天国へ旅立った。' },
 { name:'パッシングショット', years:'1987〜1990年', record:'27戦5勝', mainWins:['1990 CBC賞','1990 スワンステークス（2着）','1990 マイルチャンピオンシップ'],
   text:'トウショウボーイの仔で、1987年にデビューした。1988年のエリザベス女王杯は9着、1989年の安田記念は6着と、G1では力が届かなかった。1990年のCBC賞は好位から伸び、バンブーメモリーを3/4馬身退けて約1年半ぶりに重賞を勝った。続く高松宮杯は10着だった。秋のスワンステークスは逃げたナルシスノワールを捕らえきれず2着だった。マイルチャンピオンシップは10番人気で、スタートで出遅れた。直線で末脚を伸ばし、最後に単枠指定のバンブーメモリーを差し切ってG1を初めて勝った。鞍上にとっても初めてのG1勝利だった。スプリンターズステークスは2番人気だったが、パドックで落ち着かず、ゲートの前で放馬し、スタートでも大きく出遅れて8着に終わった。これが最後のレースになった。生まれた牧場で繁殖に入ったが、最初の種付けの準備中に転倒して頭の骨を折り、1991年に6歳で生涯を閉じた。' },
 { name:'コスモドリーム', years:'1988〜1989年', record:'13戦4勝', mainWins:['1988 優駿牝馬','1988 小倉記念（2着）','1988 京都大賞典（2着）','1989 オーストラリアトロフィー'],
   text:'1988年1月に京都の新馬戦でデビューした。優駿牝馬は22頭立ての10番人気だった。先行した馬たちが早めに動いて止まるなか、後方で待ち、坂を上ってから末脚を伸ばした。11番人気のマルシゲアトラスを下して勝ち、波乱の決着になった。鞍上は見習騎手で、オークスに初めて乗って勝った。夏は古馬と戦い、高松宮杯ではオグリキャップに大きく離された3着だった。小倉記念は1番人気で、プレジデントシチーとの写真判定にハナ差で敗れた。京都大賞典も1番人気だったが、逃げたメイショウエイカンに3馬身離された2着だった。このあと骨折が分かり、エリザベス女王杯には出られなかった。1989年はオーストラリアトロフィーを勝ったが、宝塚記念は14着だった。高松宮杯9着を最後に引退し、繁殖に入って13頭の仔を残した。' },
 { name:'オサイチジョージ', years:'1988〜1991年', record:'23戦8勝', mainWins:['1989 中日スポーツ賞4歳ステークス','1989 神戸新聞杯','1990 スポーツニッポン賞金杯','1990 中京記念','1990 宝塚記念'],
   text:'1988年9月にデビューした。1989年のニュージーランドトロフィー4歳ステークスは1番人気で3着、東京優駿には出なかった。夏の中日スポーツ賞4歳ステークスでマルセイグレートをクビ差差し切り、重賞を初めて勝った。秋の神戸新聞杯は単枠指定の1番人気で、3馬身以上の差をつけた。京都新聞杯はバンブービギンの2着、菊花賞は12着に大敗した。1990年は金杯（西）を1番人気で勝ち、中京記念はトップハンデでタニノスイセイをアタマ差差し切った。産経大阪杯はスーパークリークの2着、安田記念はオグリキャップの3着だった。宝塚記念ではオグリキャップより前で運び、そのまま押し切って3馬身半差で勝った。鞍上にとっても初めてのG1勝利だった。秋の天皇賞は4着に入り、1991年の有馬記念8着で引退した。種牡馬としては地方の重賞勝ち馬を出したが、1999年に用途変更された。' },
 { name:'シャダイカグラ', years:'1988〜1989年', record:'11戦7勝', mainWins:['1988 京都3歳ステークス','1989 ペガサスステークス','1989 桜花賞','1989 優駿牝馬（2着）','1989 ローズステークス'],
   text:'1988年6月にデビューし、京都3歳ステークスなどを勝った。ラジオたんぱ杯3歳牝馬ステークスは1番人気だったが、逃げたタニノターゲットにわずかに届かず2着だった。1989年はエルフィンステークスを勝ち、ペガサスステークスも1番人気でナルシスノワールとの競り合いを制した。桜花賞は大外18番からスタートで出遅れた。鞍上の手綱さばきで巻き返し、直線でホクトビーナスを交わした。大外枠からの桜花賞制覇は1961年のスギヒメ以来だった。優駿牝馬は単勝1.8倍の1番人気だったが、ライトカラーにわずかな差で届かず2着だった。秋はローズステークスを1.6倍の1番人気で勝った。エリザベス女王杯も1番人気だったが、途中で失速して20着に沈み、右前脚の繋靭帯断裂が分かって引退した。この年の最優秀4歳牝馬に選ばれた。繁殖では仔出しが悪く、2005年にこの世を去った。' },
 { name:'ロジータ', years:'1988〜1990年', record:'15戦10勝', mainWins:['1989 羽田盃','1989 東京ダービー','1989 東京王冠賞','1989 東京大賞典','1990 川崎記念'],
   text:'川崎競馬の牝馬で、15戦のすべてに同じ主戦騎手が乗った。1988年に2歳でデビューし、翌1989年は年明けから重賞を3連勝したあと、牝馬の路線ではなく牡馬の三冠路線へ進んだ。羽田盃と東京ダービーを楽に勝ち、秋に東京王冠賞を取って牝馬で南関東三冠を達成した。中央との交流競走のオールカマーでは初めての芝でオグリキャップの5着に入り、ジャパンカップは15着に敗れた。暮れの東京大賞典では古馬を相手に馬なりのまま圧勝した。1990年の川崎記念を引退レースに選び、単勝1.0倍の支持に8馬身差で応えた。繁殖牝馬としては帝王賞と川崎記念を勝ったカネツフルーヴを産み、孫のレギュラーメンバーも川崎記念を勝って3代での制覇となった。川崎競馬に牝馬の重賞「ロジータ記念」が残り、2016年に30歳で永眠した。' },
 { name:'ウィナーズサークル', years:'1988〜1989年', record:'11戦3勝', mainWins:['1989 皐月賞 2着','1989 東京優駿'],
   text:'茨城県の牧場で生まれた芦毛の牡馬で、名は競馬場の表彰の場から取られた。1988年夏に福島でデビューしたが芝では勝てず、翌年ダートに移って2勝を挙げた。2勝馬のため抽選で出た1989年の皐月賞は、不良馬場を中団から追い込み、ドクタースパートに半馬身届かず2着だった。東京優駿へはトライアルを使わずに向かい、3番人気で出走した。中団で折り合い、直線で馬場の中央から抜け出して、リアルバースデーとサーペンアップに半馬身差をつけて勝った。芦毛の馬として初めて、茨城県産の馬としても初めてのダービー馬で、重賞を勝たないままの戴冠でもあった。秋は京都新聞杯4着、菊花賞10着に敗れ、菊花賞のレース中に骨折していたことが分かった。1989年のJRA賞最優秀4歳牡馬に選ばれたが、復帰はかなわず1990年に引退した。種牡馬としては大きな産駒を出せず、晩年は大学の牧場で実習の相手を務め、2016年に30歳で天国へ旅立った。' },
 { name:'バンブービギン', years:'1988〜1989年', record:'12戦5勝', mainWins:['1989 神戸新聞杯 2着','1989 京都新聞杯','1989 菊花賞'],
   text:'1982年のダービー馬バンブーアトラスの仔で、父と同じ厩舎に入った。父は神戸新聞杯で故障して菊花賞に出られず、その菊花賞を仔で取ることが陣営の目標になった。1988年秋のデビューから6戦勝てず、管骨のひびで3か月休んだ。1989年5月の復帰戦を5馬身差で勝ち、そこから3連勝した。父が故障した神戸新聞杯でオサイチジョージの2着に入り、続く京都新聞杯ではその相手を後ろからマークして差し切った。1番人気の菊花賞は好位で運び、直線で外からレインボーアンバーを捕らえて1馬身半差で勝った。この年のJRA賞最優秀父内国産馬に選ばれた。翌年は天皇賞（春）を目指したが骨折し、復帰を前に屈腱炎が見つかって1991年に引退した。種牡馬としては中央の重賞勝ち馬を出せず、2012年に26歳で息を引き取った。' },
 { name:'ドクタースパート', years:'1988〜1990年', record:'18戦7勝（地方7戦4勝・中央11戦3勝）', mainWins:['1988 北海道3歳優駿','1988 京成杯3歳ステークス','1989 皐月賞','1990 ステイヤーズステークス'],
   text:'ホッカイドウ競馬でデビューし、1988年の北海道3歳優駿を2馬身差で勝つなど4連勝した。その秋に中央へ移り、初めての芝となった京成杯3歳ステークスを最後方から追い込んで、アタマ差で勝った。ホッカイドウ競馬から移った馬が中央の重賞を勝ったのは初めてだった。1989年の皐月賞は不良馬場で行われ、中団の外から第3コーナーで押し上げて、ウィナーズサークルに半馬身差をつけて勝った。地方出身の皐月賞馬はハイセイコー以来2頭目で、鞍上にとってもデビュー15年目で初めてのG1だった。その後は東京優駿14着から、ダートの帝王賞まで条件を替えながら8連敗した。1990年のステイヤーズステークスで初めて3000mを超える距離に挑み、ミスターアダムスをクビ差退けてコースレコードで勝った。直後に屈腱炎が見つかって引退し、種牡馬としては中央の活躍馬を出せなかった。' },
 { name:'サクラホクトオー', years:'1988〜1991年', record:'14戦5勝', mainWins:['1988 朝日杯3歳ステークス','1989 セントライト記念','1989 有馬記念 3着','1990 アメリカジョッキークラブカップ'],
   text:'1988年のダービー馬サクラチヨノオーの半弟で、父はトウショウボーイ。1988年10月に東京でデビューして勝ち、続く府中3歳ステークスをレコードで勝った。暮れの朝日杯3歳ステークスも単枠指定に応えて3連勝とし、前年の兄に続いて兄弟でこのレースを制した。この年の最優秀3歳牡馬に選ばれた。翌1989年は弥生賞と皐月賞がどちらも不良馬場になり、弥生賞12着、皐月賞は完走した馬の中で最下位に終わった。主戦騎手は、馬場が少しでも渋ると走る気をなくす馬だと話し、雨が苦手という印象が広まった。秋はセントライト記念を勝ち、菊花賞5着のあと、有馬記念では後方からイナリワンの3着に入った。1990年のアメリカジョッキークラブカップを勝ったが、その後は振るわず、1991年の安田記念を最後に引退した。種牡馬としては京成杯と共同通信杯4歳ステークスを勝ったサクラスピードオーを出した。' },
 { name:'ライトカラー', years:'1988〜1990年', record:'12戦3勝', mainWins:['1988 クローバー賞','1988 函館3歳ステークス 2着','1989 優駿牝馬'],
   text:'生まれて間もなく脚のつけ根を病み、手術の跡で背が曲がって見えるほどだったが、競走馬になった。1988年8月に函館でデビュー勝ちし、クローバー賞も勝って、函館3歳ステークスはアタマ差の2着だった。1989年の桜花賞は直前に熱を出し、直線で右へもたれて8着に敗れた。トライアルで5着に入って出た優駿牝馬は10番人気で、圧倒的な人気のシャダイカグラの後ろを追走した。右にもたれる癖で他の馬の邪魔をしないよう、直線で大外へ持ち出すと、そこからまっすぐ伸びた。シャダイカグラと並んでゴールし、クビ差だけ先に出ていた。単勝3480円は当時の優駿牝馬で2番目に高い配当だった。秋はローズステークスとエリザベス女王杯でともに8着に終わり、1年休んだ1990年のスワンステークスを最後に引退した。繁殖に入って2頭目の仔の出産を前に骨折し、1993年にこの世を去った。' },
 // ===== 2026-10-16 に足した名馬 =====
 { name:'ヤシマナシヨナル', years:'1966〜1973年', record:'83戦28勝', mainWins:['1968 大井記念','1969 東京盃','1969 東京オリンピック記念','1969 東京大賞典'],
   text:'1964年に生まれ、父はチャイナロック。中山の厩舎に入って1967年のクラシックを目指したが、出たのは弥生賞くらいで、中央競馬では23戦4勝だった。1968年に大井へ移り、4戦目で大井記念を勝った。この年の東京大賞典は3着。1969年の秋に東京盃（ダート1200m）、62kgを背負った東京オリンピック記念（ダート2400m）、東京大賞典を勝ち、この年の公営日本一に選ばれた。その後は南関東のハンデ戦で65kgを超える斤量を課され、1971年に宇都宮競馬場へ移った。ここで76kgを背負った幸の湖特別をコースレコードで勝った。戦後のサラブレッドの勝ち馬としては最も重い斤量だった。1972年に高知競馬場へ移り、記録の残る限り9戦9勝をあげた。種牡馬になる予定だったが、1973年1月の厩舎の火災に遭い、生涯を閉じた。' },
 { name:'ホスピタリティ', years:'1981〜1983年', record:'11戦10勝', mainWins:['1981 青雲賞','1982 京浜盃','1982 黒潮盃','1982 羽田盃','1982 セントライト記念'],
   text:'1979年に生まれ、父はテュデナム。1981年6月に大井の新馬戦でデビューし、10馬身差で逃げ切った。5連勝で3歳の王者を決める青雲賞を勝った。1982年は京浜盃、レコードタイの黒潮盃、羽田盃を勝ったが、東京ダービーの前に膝の靭帯炎を起こして出走を取り消した。7月に中央競馬へ移り、10月のセントライト記念で皐月賞馬アズマハンターに3馬身差をつけて勝った。クラシックの登録が無く、菊花賞には出られなかった。次の東京のオープン戦で、カナダのフロストキングに差されて2着に敗れた。これが生涯ただ一度の負けになった。脚を痛めて休み、1983年10月のオータムスプリントステークスを逃げ切ったが、靭帯炎が再発して引退した。種牡馬として皐月賞馬ドクタースパートなどを出し、1992年には地方競馬のリーディングサイアーになった。2008年に永眠した。' },
 { name:'ゴールドレツト', years:'1981〜1983年', record:'23戦20勝', mainWins:['1982 東海ダービー','1982 岐阜金賞','1982 東海菊花賞','1982 名古屋大賞典','1983 東海大賞典'],
   text:'1979年に静内で生まれた黒鹿毛の牡馬で、名古屋の厩舎に入った。1981年にデビューし、この年は6戦5勝、2着1回だった。1982年は1月の新春ジュニアを勝ち、中京のスプリングカップ、中日スポーツ杯に続いて、6月の東海ダービー（ダート1900m）を勝った。7月の岐阜王冠賞は2着だったが、10月に笠松の岐阜金賞、11月に東海菊花賞（ダート2400m）、12月に名古屋大賞典を勝った。この年は13戦12勝、2着1回。1983年は1月の新春グランプリ、4月に笠松の東海大賞典（ダート2500m）を勝ち、12月の名古屋大賞典で2着だった。通算23戦20勝で、残る3戦もすべて2着だった。引退後は種牡馬になった。' },
 { name:'コトノアサブキ', years:'1977〜1982年', record:'30戦23勝', mainWins:['1980 大平原賞','1980 道営記念','1981 瑞穂賞','1982 道営記念'],
   text:'1975年に生まれ、父はファーストファミリー。1977年に川崎でデビューして3連勝したが、重い屈腱炎を起こし、1978年は羽田盃10着、東京ダービー5着に終わった。名古屋へ移って条件戦を3連勝したのち、1年1か月休んだ。1980年に道営競馬へ移り、初戦の大平原賞（帯広、ダート1800m）を1分49秒7で勝った。当時のダート1800mの日本レコードだった。この年は金杯、農林水産大臣賞典、道営記念を含めて6戦6勝。1981年は瑞穂賞とシルバーカップを勝ち、道営記念は10着に敗れたが、10日後の日本中央競馬会理事長賞を勝った。1982年は大井の中央競馬招待でアズマキングの2着に入り、道営へ戻って大平原賞、理事長賞、金杯、道営記念を勝って引退した。名古屋へ移ってからの負けは2回だけだった。種牡馬としてソーエームテキなどを出した。' },
 { name:'ダイニコトブキ', years:'1957〜1962年', record:'59戦29勝', mainWins:['1958 大井盃','1958 春の鞍','1958 秋の鞍','1961 大井記念','1962 ダイオライト記念'],
   text:'1955年に生まれたサラ系の牡馬で、父はシマタカ。船橋の厩舎に入り、デビューした1957年は8戦して条件戦を2勝しただけだった。1958年に力をつけ、4月に浦和の桜花賞と大井盃（いまの羽田盃）を続けて勝った。春の鞍（いまの東京ダービー）は2番手から残り800mで先頭に立って勝った。8月には浦和のゴールドカップを60kgで勝ち、この年のサラブレッドの同世代限定の重賞をすべて勝った。NTV盃も勝ったが、金盃でヨシフサの2着に敗れて連勝は8で止まった。年末の秋の鞍（いまの東京大賞典）は2600mを逃げ切り、南関東出身の馬として初めて勝った。この年は18戦15勝。中央競馬へ移ったが3戦して勝てず、休養ののち船橋へ戻り、1961年の大井記念、1962年のダイオライト記念を勝った。引退後は種牡馬になった。' },
]);
})();
